// data/chapters.js — 全书 361 张章节卡
// year/month/place/chars 由 scripts/build_chapters.py 从 corpus/ 自动抽取；
// gist（自撰概述）来自 data/proposals/notes_*.py，经 scripts/merge_proposals.js 合并。
const CHAPTERS = [
  { id:"1-1-01", book:1, part:1, ch:1, seq:1, year:1805, month:7, tag:"peace", place:"彼得堡", chars:["anna_sherer","vasily"], gist:"舍勒家晚会开场。女主人与华西里公爵谈战事与拿破仑，并盘算把阿纳托里配给玛丽雅公爵小姐。", flag:null },
  { id:"1-1-02", book:1, part:1, ch:2, seq:2, year:null, month:null, tag:"peace", place:"彼得堡", chars:["anna_sherer","vasily","helen","hippolyte","liza","pierre"], gist:"宾客陆续到场：美人海伦、伊波利特、小公爵夫人丽莎与莫特玛子爵。笨拙的私生子皮埃尔首次露面。", flag:null },
  { id:"1-1-03", book:1, part:1, ch:3, seq:3, year:null, month:null, tag:"peace", place:"彼得堡", chars:["anna_sherer","pierre","andrei","helen","vasily","hippolyte"], gist:"客厅里争辩拿破仑枪杀当甘公爵的旧事。皮埃尔为拿破仑辩护，安德烈现身并与皮埃尔重逢。", flag:null },
  { id:"1-1-04", book:1, part:1, ch:4, seq:4, year:null, month:null, tag:"peace", place:"彼得堡", chars:["anna_mikh","vasily","boris","pierre","andrei","hippolyte","anna_sherer"], gist:"安娜·米哈伊洛夫娜求华西里公爵把儿子保里斯调入近卫军。皮埃尔为革命辩护遭围攻，安德烈出言相助。", flag:null },
  { id:"1-1-05", book:1, part:1, ch:5, seq:5, year:null, month:null, tag:"peace", place:"彼得堡", chars:["pierre","andrei","liza","hippolyte","anna_sherer"], gist:"散场后皮埃尔随安德烈回保尔康斯基家，两人谈前途与选择；伊波利特送别小公爵夫人。", flag:null },
  { id:"1-1-06", book:1, part:1, ch:6, seq:6, year:null, month:null, tag:"peace", place:"彼得堡", chars:["pierre","andrei","liza","anatole","dolokhov"], gist:"安德烈与妻子为出征争吵，又劝皮埃尔别结婚。皮埃尔转赴阿纳托里的酒局，陶洛霍夫与人打赌。", flag:null },
  { id:"1-1-07", book:1, part:1, ch:7, seq:7, year:null, month:null, tag:"peace", place:"莫斯科", chars:["ilya","countess_r","anna_mikh","natasha"], gist:"场景转到莫斯科罗斯托夫家。命名日在即，众人议论老别祖霍夫病危、皮埃尔被逐与遗产归属。", flag:null },
  { id:"1-1-08", book:1, part:1, ch:8, seq:8, year:null, month:null, tag:"peace", place:"莫斯科", chars:["natasha","nikolai","petya","sophia","boris"], gist:"罗斯托夫家的小辈在客厅嬉闹：娜塔莎、尼古拉、彼嘉、宋尼雅与保里斯，还有布娃娃的插曲。", flag:null },
  { id:"1-1-09", book:1, part:1, ch:9, seq:9, year:null, month:null, tag:"peace", place:"莫斯科", chars:["ilya","countess_r","nikolai","sophia","vera","natasha"], gist:"客厅日常：伯爵谈尼古拉从军，伯爵夫人谈子女教育；尼古拉与宋尼雅的神情被家人看在眼里。", flag:null },
  { id:"1-1-10", book:1, part:1, ch:10, seq:10, year:null, month:null, tag:"peace", place:"莫斯科", chars:["natasha","nikolai","sophia","boris"], gist:"娜塔莎躲在花房，撞见尼古拉与宋尼雅相拥；她随后把保里斯叫来，两人在花房初次说情。", flag:null },
  { id:"1-1-11", book:1, part:1, ch:11, seq:11, year:null, month:null, tag:"peace", place:"莫斯科", chars:["natasha","boris","sophia","nikolai","vera","countess_r","anna_mikh"], gist:"起居室里两对少年情人同薇拉口角。伯爵夫人向安娜·米哈伊洛夫娜诉苦，后者哭穷，指望别祖霍夫的遗产。", flag:null },
  { id:"1-1-12", book:1, part:1, ch:12, seq:12, year:null, month:null, tag:"peace", place:"莫斯科", chars:["anna_mikh","boris","vasily","kirill","katya"], gist:"安娜·米哈伊洛夫娜带保里斯探病，在别祖霍夫家遇见华西里公爵，随即决定留下照看病人。", flag:null },
  { id:"1-1-13", book:1, part:1, ch:13, seq:13, year:null, month:null, tag:"peace", place:"莫斯科", chars:["pierre","boris","anna_mikh","katya"], gist:"皮埃尔在莫斯科父亲的宅中；保里斯来访，两人长谈。另一头，安娜·米哈伊洛夫娜母子在议论遗嘱。", flag:null },
  { id:"1-1-14", book:1, part:1, ch:14, seq:14, year:null, month:null, tag:"peace", place:"莫斯科", chars:["countess_r","ilya"], gist:"伯爵夫人向丈夫讨五百卢布，替保里斯置办军装；夫妻相对落泪。", flag:null },
  { id:"1-1-15", book:1, part:1, ch:15, seq:15, year:null, month:null, tag:"peace", place:"莫斯科", chars:["ilya","countess_r","ahrosimova","berg","vera","natasha"], gist:"罗斯托夫家命名日宴请。教母阿赫罗西莫娃到场，别尔格在书房谈前程，宾客入席。", flag:null },
  { id:"1-1-16", book:1, part:1, ch:16, seq:16, year:null, month:null, tag:"peace", place:"莫斯科", chars:["ilya","countess_r","nikolai","natasha","ahrosimova"], gist:"席间谈宣战与拿破仑。一位骠骑兵上校发言，尼古拉插话；娜塔莎当众问起甜点，惹得满座发笑。", flag:null },
  { id:"1-1-17", book:1, part:1, ch:17, seq:17, year:null, month:null, tag:"peace", place:"莫斯科", chars:["natasha","nikolai","sophia","ilya","ahrosimova","boris","vera"], gist:"年轻人唱歌。尼古拉为写给宋尼雅的诗动情，姐妹俩谈心；伯爵与阿赫罗西莫娃跳起俄罗斯舞。", flag:null },
  { id:"1-1-18", book:1, part:1, ch:18, seq:18, year:null, month:null, tag:"peace", place:"莫斯科", chars:["kirill","vasily","katya","anna_mikh"], gist:"别祖霍夫家为垂危的老伯爵行终敷礼。华西里公爵与卡嘉公爵小姐私下计议藏匿遗嘱。", flag:null },
  { id:"1-1-19", book:1, part:1, ch:19, seq:19, year:null, month:null, tag:"peace", place:"莫斯科", chars:["pierre","anna_mikh","katya"], gist:"皮埃尔随安娜·米哈伊洛夫娜回父亲宅第，在老伯爵的接待室里等候，众人叫他进去。", flag:null },
  { id:"1-1-20", book:1, part:1, ch:20, seq:20, year:null, month:null, tag:"peace", place:"莫斯科", chars:["pierre","kirill","vasily","katya","anna_mikh"], gist:"皮埃尔进入病室。终敷礼进行，公侯、神父、医生与仆从环列，老伯爵想见儿子却说不出话。", flag:null },
  { id:"1-1-21", book:1, part:1, ch:21, seq:21, year:null, month:null, tag:"peace", place:"莫斯科", chars:["pierre","kirill","vasily","katya","anna_mikh"], gist:"争夺公文包的一幕：华西里公爵与卡嘉扑空，皮埃尔拿到遗嘱。老伯爵去世。", flag:null },
  { id:"1-1-22", book:1, part:1, ch:22, seq:22, year:null, month:null, tag:"peace", place:"童山", chars:["old_prince","marya","bourienne"], gist:"场景转向童山。老公爵用几何课折磨女儿玛丽雅，裘丽的来信引出一段回信。", flag:null },
  { id:"1-1-23", book:1, part:1, ch:23, seq:23, year:null, month:null, tag:"peace", place:"童山", chars:["andrei","liza","marya","old_prince","bourienne"], gist:"安德烈夫妇抵达童山，与妹妹及法国女伴布莉恩相见；父子谈战事与政局。", flag:null },
  { id:"1-1-24", book:1, part:1, ch:24, seq:24, year:null, month:null, tag:"peace", place:"童山", chars:["old_prince","andrei","marya","mikhail","liza"], gist:"童山家宴上父子为苏沃洛夫与拿破仑争辩，建筑师米哈伊尔·伊凡内奇同席受冷遇。", flag:null },
  { id:"1-1-25", book:1, part:1, ch:25, seq:25, year:null, month:null, tag:"peace", place:"童山", chars:["andrei","marya","old_prince","liza"], gist:"安德烈辞别家人出征。玛丽雅把圣像挂到他身上，老公爵叮嘱，小公爵夫人昏厥。", flag:null },
  { id:"1-2-01", book:1, part:2, ch:1, seq:26, year:1805, month:10, tag:"war", place:"布劳瑙", chars:["dolokhov"], gist:"一八〇五年十月，俄团开抵布劳瑙候库图佐夫检阅，连夜缝洗整队；司令部却传令保持行军破装，蓝大衣的陶洛霍夫顶撞团长。", flag:null },
  { id:"1-2-02", book:1, part:2, ch:2, seq:27, year:null, month:null, tag:"war", place:"布劳瑙", chars:["kutuzov","dolokhov","andrei","nesvitsky"], gist:"库图佐夫偕奥将检阅，屡指士兵破靴示意盟军；经安德烈提醒召见降职的陶洛霍夫。行军歌声里热尔科夫约陶洛霍夫赌酒被拒。", flag:null },
  { id:"1-2-03", book:1, part:2, ch:3, seq:28, year:null, month:null, tag:"war", place:"布劳瑙", chars:["kutuzov","andrei","nesvitsky"], gist:"司令部里库图佐夫同奥国参议口是心非地扯皮；头缠黑布的马克来报乌尔姆全军投降。安德烈痛斥拿盟军覆没开玩笑的热尔科夫。", flag:null },
  { id:"1-2-04", book:1, part:2, ch:4, seq:29, year:1805, month:10, tag:"war", place:"布劳瑙", chars:["nikolai","denisov","zhilinsky","lavrushka"], gist:"尼古拉在骠骑兵团同连长杰尼索夫合住。杰尼索夫通宵输牌后发现钱包失窃，尼古拉追到小酒店，当面揭穿吉梁宁的偷窃。", flag:null },
  { id:"1-2-05", book:1, part:2, ch:5, seq:30, year:null, month:null, tag:"war", place:"布劳瑙", chars:["nikolai","denisov"], gist:"军官夜议失窃风波：吉尔斯顿劝尼古拉向团长道歉以保全团名誉，尼古拉认错了却不肯低头；热尔科夫带回马克投降、明日开仗的消息。", flag:null },
  { id:"1-2-06", book:1, part:2, ch:6, seq:31, year:1805, month:10, tag:"war", place:"恩斯河", chars:["nesvitsky"], gist:"十月二十三日俄军渡恩斯河，聂斯维茨基奉命催骠骑兵最后过桥并焚桥；后卫高地上炮兵试炮解闷，敌骑已现于对岸远山。", flag:null },
  { id:"1-2-07", book:1, part:2, ch:7, seq:32, year:null, month:null, tag:"war", place:"恩斯河", chars:["nesvitsky","denisov"], gist:"桥上人流如决堤，炮弹落进急流；杰尼索夫挥刀喝开拥堵，与聂斯维茨基打通桥面。骠骑兵整齐过桥，步兵隔队冷嘲热骂。", flag:null },
  { id:"1-2-08", book:1, part:2, ch:8, seq:33, year:null, month:null, tag:"war", place:"恩斯河", chars:["nikolai","denisov","nesvitsky"], gist:"法军炮击木桥，烧桥命令传得磕绊，团长终究带人点火成功，只折三人；尼古拉初历炮火，在担架与夕阳之间尝到恐惧。", flag:null },
  { id:"1-2-09", book:1, part:2, ch:9, seq:34, year:1805, month:10, tag:"war", place:"布尔诺", chars:["andrei","kutuzov"], gist:"库图佐夫沿多瑙河退却，十月三十日在克雷姆斯初胜法军一师；安德烈负轻伤雪夜赴布尔诺递捷报，遭奥国陆军大臣冷待。", flag:null },
  { id:"1-2-10", book:1, part:2, ch:10, seq:35, year:null, month:null, tag:"peace", place:"布尔诺", chars:["andrei","bilbin"], gist:"安德烈下榻比利平家。外交官泼冷水：维也纳已陷落，拿破仑进了申勃隆，这场捷报在奥国宫廷眼里近乎捣蛋，大局系于普鲁士。", flag:null },
  { id:"1-2-11", book:1, part:2, ch:11, seq:36, year:null, month:null, tag:"peace", place:"布尔诺", chars:["andrei","bilbin","hippolyte"], gist:"比利平书房里聚着使馆的公子圈：伊波利特公爵一本正经胡说照会，引来哄笑；众人张罗作乐招待，安德烈看表动身去朝见弗朗茨皇帝。", flag:null },
  { id:"1-2-12", book:1, part:2, ch:12, seq:37, year:null, month:null, tag:"war", place:"布尔诺", chars:["andrei","franz","bilbin"], gist:"朝觐只剩例行问答与授勋；回来却听说泰波桥未炸、缪拉骗过桥头堡，法军扑向布尔诺。安德烈不顾挽留，连夜赶回部队。", flag:null },
  { id:"1-2-13", book:1, part:2, ch:13, seq:38, year:null, month:null, tag:"war", place:"克雷姆斯", chars:["andrei","kutuzov","bagration","nesvitsky"], gist:"安德烈穿过溃乱辎重队赶往前线，替军医太太出头反遭辱骂；库图佐夫画十字送巴格拉基昂断后，料其部十不存一。", flag:null },
  { id:"1-2-14", book:1, part:2, ch:14, seq:39, year:1805, month:11, tag:"war", place:"霍拉勃隆", chars:["kutuzov","bagration","murat","napoleon"], gist:"十一月一日法军过桥断退路；巴格拉基昂强行军抢占霍拉勃隆；缪拉中计提议休战三日，拿破仑怒信催战，饿兵犹烤火煮粥。", flag:null },
  { id:"1-2-15", book:1, part:2, ch:15, seq:40, year:null, month:null, tag:"war", place:"霍拉勃隆", chars:["andrei","bagration","tushin","dolokhov"], gist:"安德烈到格仑特加入巴格拉基昂司令部，巡阵结识脱靴烤火的炮长土申；散兵线上陶洛霍夫同法国掷弹兵隔线斗嘴，两边士兵哄成一片。", flag:null },
  { id:"1-2-16", book:1, part:2, ch:16, seq:41, year:null, month:null, tag:"war", place:"申格拉本", chars:["andrei","tushin"], gist:"安德烈在土申炮垒望见全队阵势，草图建议集中炮兵、后撤骑兵；棚内炮兵正议论死后有无来世，一颗炮弹轰然落在近旁，战斗开始。", flag:null },
  { id:"1-2-17", book:1, part:2, ch:17, seq:42, year:null, month:null, tag:"war", place:"申格拉本", chars:["andrei","bagration","tushin"], gist:"缪拉急于补过提前进攻；巴格拉基昂慢条斯理巡至土申炮垒，军法官笑问炮弹时身旁哥萨克中弹倒地；土申自专炮击，点燃申格拉本村。", flag:null },
  { id:"1-2-18", book:1, part:2, ch:18, seq:43, year:null, month:null, tag:"war", place:"申格拉本", chars:["andrei","bagration"], gist:"右翼残部混战中，风卷硝烟露出法军纵队；巴格拉基昂忽展杀气，下马步行高呼上帝保佑，第六猎骑兵踏着拍子涌下山坡冲锋。", flag:null },
  { id:"1-2-19", book:1, part:2, ch:19, seq:44, year:null, month:null, tag:"war", place:"申格拉本", chars:["nikolai","denisov"], gist:"左翼两团长赌气误事，骠骑兵退路被断；杰尼索夫下令冲锋，尼古拉狂驰在先，连人带马被扫倒，醒来孤身逃命，扔出手枪狂奔。", flag:null },
  { id:"1-2-20", book:1, part:2, ch:20, seq:45, year:null, month:null, tag:"war", place:"申格拉本", chars:["andrei","tushin","dolokhov"], gist:"基莫兴一连反冲挽回溃散的左翼，陶洛霍夫俘敌讨赏；被遗忘的土申以四炮顶住敌十炮，安德烈奉命传撤，陪他火中拖炮。", flag:null },
  { id:"1-2-21", book:1, part:2, ch:21, seq:46, year:null, month:null, tag:"war", place:"申格拉本", chars:["tushin","nikolai","andrei","bagration"], gist:"夜撤：尼古拉搭上土申的炮车，篝火边疼痛思家；农舍里败报粉饰成战功，安德烈为丢炮受责的土申执言。次日残部与主力会师。", flag:null },
  { id:"1-3-01", book:1, part:3, ch:1, seq:47, year:1805, month:null, tag:"peace", place:"彼得堡", chars:["pierre","vasily","helen","anna_sherer"], gist:"皮埃尔继承巨额遗产，被华西里公爵带到彼得堡安插职位；在舍勒晚会上他惊觉海伦的肉体魅力，预感到这门婚事将至。", flag:null },
  { id:"1-3-02", book:1, part:3, ch:2, seq:48, year:1805, month:11, tag:"peace", place:"彼得堡", chars:["pierre","helen","vasily","kuragina","anna_sherer"], gist:"海伦命名日家宴，众人目光都盯着迟迟不求婚的皮埃尔；华西里公爵促成了订婚，一个半月后两人成婚。", flag:null },
  { id:"1-3-03", book:1, part:3, ch:3, seq:49, year:1805, month:12, tag:"peace", place:"童山", chars:["vasily","anatole","old_prince","marya","liza","bourienne","tihon"], gist:"一八〇五年十二月，华西里父子抵童山为阿纳托里向玛丽雅求婚；老公爵一肚子火，迁怒仆人又奚落女儿的穿戴。", flag:null },
  { id:"1-3-04", book:1, part:3, ch:4, seq:50, year:null, month:null, tag:"peace", place:"童山", chars:["marya","anatole","bourienne","old_prince","vasily","liza"], gist:"初见一场：阿纳托里嫌玛丽雅丑而醉心布莉恩，琴下踢脚调情；老公爵当面奚落女儿，私下却应下求婚并要考察女婿。", flag:null },
  { id:"1-3-05", book:1, part:3, ch:5, seq:51, year:null, month:null, tag:"peace", place:"童山", chars:["old_prince","marya","vasily","anatole","bourienne"], gist:"老公爵假意给女儿择婿自由，玛丽雅当场拒婚；她在花房撞破阿纳托里与布莉恩幽会，反去安慰对方，欲成全二人。", flag:null },
  { id:"1-3-06", book:1, part:3, ch:6, seq:52, year:null, month:null, tag:"peace", place:"莫斯科", chars:["ilya","countess_r","anna_mikh","natasha","sophia","petya","vera"], gist:"罗斯托夫家盼到尼古拉来信：负伤升了军官。全家轮流读信落泪，花一周写联名回信，托近卫军渠道转寄六千卢布。", flag:null },
  { id:"1-3-07", book:1, part:3, ch:7, seq:53, year:null, month:11, tag:"war", place:"奥尔米茨", chars:["nikolai","boris","berg","andrei"], gist:"尼古拉到奥洛莫乌茨近卫军营地找保里斯取钱收家信，吹嘘申格拉本战功；安德烈来访出言调侃，两人为决斗的事纠结。", flag:null },
  { id:"1-3-08", book:1, part:3, ch:8, seq:54, year:null, month:null, tag:"war", place:"奥尔米茨", chars:["nikolai","alexander","franz"], gist:"奥洛莫乌茨郊外八万联军接受两位皇帝检阅；尼古拉为亚历山大的风度如醉如痴，纵马驰过御前，全军盼随皇上决战。", flag:null },
  { id:"1-3-09", book:1, part:3, ch:9, seq:55, year:null, month:null, tag:"war", place:"奥尔米茨", chars:["boris","andrei","nesvitsky"], gist:"保里斯经安德烈引荐到行宫谋副官差事，见识军中不成文的从属关系；御前军事会议否决稳妥派，定下立即同拿破仑决战。", flag:null },
  { id:"1-3-10", book:1, part:3, ch:10, seq:56, year:null, month:11, tag:"war", place:"维绍", chars:["nikolai","denisov","alexander"], gist:"维绍小捷，尼古拉从法军俘虏手里买马，又见到亲临前线的亚历山大；皇帝见伤兵落泪，当晚军官们狂热为沙皇祝酒。", flag:null },
  { id:"1-3-11", book:1, part:3, ch:11, seq:57, year:null, month:11, tag:"war", place:"奥斯特里茨", chars:["andrei","kutuzov","bilbin"], gist:"和谈使节往还之间，联军像钟表机器夜里开拔走向会战；身边人断言拿破仑已恐慌，库图佐夫却对安德烈直言明日必败。", flag:null },
  { id:"1-3-12", book:1, part:3, ch:12, seq:58, year:1805, month:11, tag:"war", place:"奥斯特里茨", chars:["kutuzov","andrei"], gist:"会战前夜军事会议：威罗特宣读复杂作战部署，库图佐夫打鼾入睡，巴格拉基昂拒席；散会后安德烈雾夜憧憬属于自己的土伦。", flag:null },
  { id:"1-3-13", book:1, part:3, ch:13, seq:59, year:null, month:null, tag:"war", place:"莫斯科", chars:["nikolai","bagration","napoleon"], gist:"尼古拉雾夜巡逻，听到法军阵地万岁声，自请侦察冒着枪弹回报巴格拉基昂，被留作传令官；法军营地宣读拿破仑会战训令。", flag:null },
  { id:"1-3-14", book:1, part:3, ch:14, seq:60, year:null, month:null, tag:"war", place:"奥斯特里茨", chars:["napoleon"], gist:"拂晓联军左翼冒浓雾下山，行军停滞怨声载道，河上枪声打响；拿破仑在晴岗等到日出雾散，下令主力直取普拉岑高地。", flag:null },
  { id:"1-3-15", book:1, part:3, ch:15, seq:61, year:null, month:null, tag:"war", place:"奥斯特里茨", chars:["kutuzov","andrei","alexander","franz","nesvitsky"], gist:"库图佐夫在普拉茨迟缓布阵，两皇亲临催战，老帅语带顶撞；米洛拉多维奇激励部队开赴火线，安德烈深信今天是他的土伦日。", flag:null },
  { id:"1-3-16", book:1, part:3, ch:16, seq:62, year:null, month:null, tag:"war", place:"奥斯特里茨", chars:["andrei","kutuzov","nesvitsky"], gist:"法军忽然逼到跟前，部队溃逃；库图佐夫面颊溅血仍想拦兵，安德烈抢过军旗冲锋中弹倒地，望见高远宁静的天空。", flag:null },
  { id:"1-3-17", book:1, part:3, ch:17, seq:63, year:null, month:null, tag:"war", place:"奥斯特里茨", chars:["nikolai","bagration","boris","berg"], gist:"巴格拉基昂派尼古拉穿越战场去向总司令和皇帝请示；他目睹近卫重骑兵几近覆没的冲锋与俄奥兵互射，仍不信败局已定。", flag:null },
  { id:"1-3-18", book:1, part:3, ch:18, seq:64, year:null, month:null, tag:"war", place:"奥斯特里茨", chars:["nikolai","alexander","dolokhov"], gist:"尼古拉在溃兵中寻着亚历山大却不敢上前禀报，悔恨错失表忠心的机会；午后全线大败，堤坝上炮轰人群，陶洛霍夫喊众人踩冰逃生。", flag:null },
  { id:"1-3-19", book:1, part:3, ch:19, seq:65, year:null, month:null, tag:"war", place:"奥斯特里茨", chars:["andrei","napoleon"], gist:"拿破仑巡视战场下令救治倒地的安德烈，又在俘虏前炫耀宽宏；安德烈只觉这位英雄渺小无聊，天空才是真实，军医判断他凶多吉少。", flag:null },
  { id:"2-1-01", book:2, part:1, ch:1, seq:66, year:1806, month:null, tag:"peace", place:"莫斯科", chars:["nikolai","denisov","natasha","sophia","ilya","countess_r"], gist:"一八〇六年初尼古拉休假归家，带杰尼索夫同到莫斯科；娜塔莎说宋尼雅仍爱哥哥却不肯用旧约捆住他，自己立志不嫁人。", flag:null },
  { id:"2-1-02", book:2, part:1, ch:2, seq:67, year:1806, month:3, tag:"peace", place:"莫斯科", chars:["nikolai","ilya","anna_mikh"], gist:"尼古拉在莫斯科尽享社交生活，老伯爵筹备在英国俱乐部宴请巴格拉基昂；全市回避奥斯特里茨之败，合力造出一位俄国英雄。", flag:null },
  { id:"2-1-03", book:2, part:1, ch:3, seq:68, year:1806, month:3, tag:"peace", place:"莫斯科", chars:["ilya","bagration","nikolai","denisov","dolokhov","pierre"], gist:"三月三日英国俱乐部宴会，巴格拉基昂在簇拥下进场听颂诗入席；老伯爵穿梭张罗，带头频频祝酒，最后为主人自己干杯时感动落泪。", flag:null },
  { id:"2-1-04", book:2, part:1, ch:4, seq:69, year:1806, month:3, tag:"peace", place:"莫斯科", chars:["pierre","dolokhov","nikolai","denisov","nesvitsky"], gist:"皮埃尔被匿名信折磨，宴会上陶洛霍夫故意挑衅夺走诗句，皮埃尔当众叫嚷决斗；次日清晨双方在索科尔尼基林中空地列阵。", flag:null },
  { id:"2-1-05", book:2, part:1, ch:5, seq:70, year:1806, month:3, tag:"peace", place:"莫斯科", chars:["pierre","dolokhov","nikolai","denisov","nesvitsky"], gist:"决斗开始，皮埃尔一枪打伤陶洛霍夫；陶洛霍夫瞄准后故意射偏倒在雪地上。负伤后他只挂念母亲受惊，托付尼古拉先去报信。", flag:null },
  { id:"2-1-06", book:2, part:1, ch:6, seq:71, year:1806, month:3, tag:"peace", place:"莫斯科", chars:["pierre","helen"], gist:"决斗之夜皮埃尔彻夜自省，认清不爱而娶的错误；海伦上门申辩激怒了他，他砸碎石板吼走妻子，随即让出大半产业只身去彼得堡。", flag:null },
  { id:"2-1-07", book:2, part:1, ch:7, seq:72, year:null, month:null, tag:"peace", place:"童山", chars:["old_prince","marya","liza"], gist:"童山得知安德烈在奥斯特里茨举旗阵亡，老公爵与玛丽雅各以方式忍痛，瞒住怀孕的丽莎；公爵立碑宣称儿子已死，玛丽雅仍盼他归来。", flag:null },
  { id:"2-1-08", book:2, part:1, ch:8, seq:73, year:null, month:3, tag:"peace", place:"童山", chars:["liza","marya","old_prince","andrei"], gist:"三月十九日丽莎骤然临产，风雪夜全家屏息等待莫斯科请来的产科医生；楼梯口安德烈意外归来，他在最后一站与医生同车赶至。", flag:null },
  { id:"2-1-09", book:2, part:1, ch:9, seq:74, year:null, month:null, tag:"peace", place:"童山", chars:["andrei","liza","marya","old_prince","nikolushka"], gist:"小公爵夫人产死亡故，安德烈自觉犯下无法补救的罪过；三日后下葬，五日后为遗孤小尼古拉施洗，老公爵颤巍巍当了教父。", flag:null },
  { id:"2-1-10", book:2, part:1, ch:10, seq:75, year:1806, month:null, tag:"transition", place:"莫斯科", chars:["nikolai","dolokhov","natasha","sophia","denisov"], gist:"决斗经老伯爵奔走暗中了结，尼古拉反得当了总督副官；养伤复出的陶洛霍夫迷上宋尼雅常来罗斯托夫家，入秋全国又闹对拿破仑备战。", flag:null },
  { id:"2-1-11", book:2, part:1, ch:11, seq:76, year:1806, month:12, tag:"peace", place:"莫斯科", chars:["nikolai","dolokhov","sophia","natasha","countess_r","denisov"], gist:"罗斯托夫家饯行午宴上揭晓：陶洛霍夫向宋尼雅求婚被一口回绝。尼古拉与宋尼雅初次谈心，她表示只愿像爱哥哥一样永远爱他。", flag:null },
  { id:"2-1-12", book:2, part:1, ch:12, seq:77, year:1806, month:12, tag:"peace", place:"莫斯科", chars:["natasha","denisov","nikolai","sophia"], gist:"借皮埃尔家大厅的约盖尔舞会上，娜塔莎第一次穿舞裙乐在其中；杰尼索夫被她拉去跳玛祖卡，技惊四座，此后寸步不离她身旁。", flag:null },
  { id:"2-1-13", book:2, part:1, ch:13, seq:78, year:null, month:null, tag:"peace", place:"莫斯科", chars:["nikolai","dolokhov"], gist:"陶洛霍夫把尼古拉请去英国饭店赌局；尼古拉被激着下场，孤注一掷想翻回八百卢布，红桃七却开成第一张，越输越深。", flag:null },
  { id:"2-1-14", book:2, part:1, ch:14, seq:79, year:null, month:null, tag:"peace", place:"莫斯科", chars:["nikolai","dolokhov"], gist:"赌桌注意力全在尼古拉身上，陶洛霍夫冷静做庄，刻意把输款逼到四万三千才收手；尼古拉硬着头皮允诺次日交钱。", flag:null },
  { id:"2-1-15", book:2, part:1, ch:15, seq:80, year:null, month:null, tag:"peace", place:"莫斯科", chars:["nikolai","natasha","denisov","sophia","countess_r"], gist:"背负巨债的尼古拉回到家，自我厌弃只想子弹打进脑门；娜塔莎一开嗓唱船歌，他却被歌声攫住，一时觉得输钱与名誉都无关紧要。", flag:null },
  { id:"2-1-16", book:2, part:1, ch:16, seq:81, year:null, month:null, tag:"peace", place:"莫斯科", chars:["nikolai","ilya","denisov","natasha","countess_r","sophia"], gist:"尼古拉向父亲坦白赌输四万三千卢布，老伯爵艰难筹款替他偿清；杰尼索夫向娜塔莎求爱被婉拒，悻悻离开莫斯科。", flag:null },
  { id:"2-2-01", book:2, part:2, ch:1, seq:82, year:null, month:null, tag:"transition", place:"彼得堡", chars:["pierre"], gist:"决斗后皮埃尔赴彼得堡，在托尔若克驿站陷于善恶生死的追问；一位目光锐利的枯瘦老客闯进他的沉思。", flag:null },
  { id:"2-2-02", book:2, part:2, ch:2, seq:83, year:null, month:null, tag:"peace", place:"彼得堡", chars:["pierre","bazdeev"], gist:"老客自认共济会员，责备皮埃尔纵欲无为、辜负农奴，论上帝的话令他心服；临别写荐书给维拉尔斯基，嘱他自省更生。", flag:null },
  { id:"2-2-03", book:2, part:2, ch:3, seq:84, year:null, month:null, tag:"peace", place:"彼得堡", chars:["pierre","villarsky"], gist:"皮埃尔抵彼得堡，由维拉尔斯基做保入会，蒙眼独对骷髅与棺材，听导师讲会的三宗旨与七项美德，坦白自己好女色。", flag:null },
  { id:"2-2-04", book:2, part:2, ch:4, seq:85, year:null, month:null, tag:"peace", place:"彼得堡", chars:["pierre","villarsky"], gist:"蒙眼巡行、利剑抵胸，宣誓后得见光明；领过围裙、铲子与女手套，听罢会章受吻抱礼。皮埃尔回家，誓弃旧日生活。", flag:null },
  { id:"2-2-05", book:2, part:2, ch:5, seq:86, year:null, month:null, tag:"peace", place:"彼得堡", chars:["pierre","vasily"], gist:"华西里公爵上门替海伦说和，劝皮埃尔认错团聚；皮埃尔强压怒火把岳父轰出门，留下巨款辞别会友，动身去南方庄园。", flag:null },
  { id:"2-2-06", book:2, part:2, ch:6, seq:87, year:1806, month:null, tag:"peace", place:"彼得堡", chars:["anna_sherer","helen","boris","hippolyte"], gist:"决斗私了，海伦回彼得堡赢得同情。舍勒家晚会上，从普鲁士归来的专使保里斯新贵登场，与海伦眉来眼去。", flag:null },
  { id:"2-2-07", book:2, part:2, ch:7, seq:88, year:null, month:null, tag:"peace", place:"彼得堡", chars:["anna_sherer","helen","boris","hippolyte"], gist:"晚会上伊波利特故弄玄虚，半句笑话引人发笑；众人争辩皇帝恩赏。海伦两次暗中相约，保里斯就此成了她家的密友。", flag:null },
  { id:"2-2-08", book:2, part:2, ch:8, seq:89, year:1807, month:2, tag:"peace", place:"童山", chars:["andrei","marya","old_prince","nikolushka"], gist:"老公爵出任民团总司令出巡，安德烈避入现役留守童山。幼子高烧，兄妹两夜守病；父信限他即刻赴科尔切瓦办差。", flag:null },
  { id:"2-2-09", book:2, part:2, ch:9, seq:90, year:null, month:null, tag:"peace", place:"童山", chars:["andrei","marya","bilbin","kutuzov","bennigsen"], gist:"比利来信讽刺统帅部内讧：库图佐夫愤而辞职、普尔土斯克两司令争权、军队劫掠成灾。育儿室里孩子出汗脱险，兄妹相拥。", flag:null },
  { id:"2-2-10", book:2, part:2, ch:10, seq:91, year:null, month:null, tag:"peace", place:"彼得堡", chars:["pierre"], gist:"皮埃尔在基辅庄园宣布解放农奴、兴学办医，遭总管搪塞玩弄；巡视各处广受感恩欢迎，他不知一切照旧，反自喜行善有成。", flag:null },
  { id:"2-2-11", book:2, part:2, ch:11, seq:92, year:null, month:null, tag:"peace", place:"保古察罗伏", chars:["pierre","andrei"], gist:"皮埃尔访保古察罗伏，安德烈眼神呆滞只谈盖房。餐桌与台阶上两人争辩：一个说为别人活才幸福，一个说为自己活才心安。", flag:null },
  { id:"2-2-12", book:2, part:2, ch:12, seq:93, year:null, month:null, tag:"peace", place:"童山", chars:["pierre","andrei"], gist:"渡船上皮埃尔劝安德烈信共济会与来世，安德烈说使他信服的是亡妻之痛；上岸时他重见奥斯特里茨的天空，内心开始新生。", flag:null },
  { id:"2-2-13", book:2, part:2, ch:13, seq:94, year:null, month:null, tag:"peace", place:"童山", chars:["pierre","andrei","marya"], gist:"皮埃尔在童山撞见玛丽雅公爵小姐私留的云游教徒；他失口说圣母显圣是骗人，惹得女教徒连喊罪过，只好赔礼求饶。", flag:null },
  { id:"2-2-14", book:2, part:2, ch:14, seq:95, year:null, month:null, tag:"peace", place:"童山", chars:["pierre","andrei","marya","old_prince"], gist:"皮埃尔静听女教徒讲洞窟朝圣，得玛丽雅感激；老公爵回府一见如故，饭前同他辩论战争无战之世，邀他常来。全家事后齐声称好。", flag:null },
  { id:"2-2-15", book:2, part:2, ch:15, seq:96, year:null, month:null, tag:"war", place:"普尔土斯克", chars:["nikolai","denisov"], gist:"尼古拉假满归队如归家。部队困在德语区荒村断粮，士兵靠苦草根充饥、浮肿流行；他收留波兰难民父女，因同事讥讽险又决斗。", flag:null },
  { id:"2-2-16", book:2, part:2, ch:16, seq:97, year:null, month:null, tag:"war", place:null, chars:["denisov","nikolai","zhilinsky","lavrushka"], gist:"杰尼索夫带骠骑兵截下步兵辎重救饥，到军需处认出饿部队的正是吉梁宁，怒打同僚；风闻军法调查，借腿部轻伤躲进医院。", flag:null },
  { id:"2-2-17", book:2, part:2, ch:17, seq:98, year:null, month:null, tag:"war", place:"弗里德兰", chars:["nikolai"], gist:"停战期尼古拉到普鲁士小镇医院探友，医生误传杰尼索夫已死；士兵病房伤寒横行，哥萨克讨水、尸体无人抬，他看得骇然。", flag:null },
  { id:"2-2-18", book:2, part:2, ch:18, seq:99, year:null, month:null, tag:"war", place:"埃劳", chars:["nikolai","denisov","tushin"], gist:"军官病房重逢断臂的土申。土申劝向皇上求恩，杰尼索夫念尖刻答辩拒不服软，终究无可奈何，把呈文托尼古拉递上去。", flag:null },
  { id:"2-2-19", book:2, part:2, ch:19, seq:100, year:null, month:6, tag:"peace", place:"蒂尔西特", chars:["nikolai","boris","napoleon","alexander"], gist:"尼古拉携呈文到蒂尔西特；保里斯亲历两国皇帝木筏会晤、挤进近侍圈子。尼古拉撞进法军军官的宴席格格不入，保里斯推诿不帮忙。", flag:null },
  { id:"2-2-20", book:2, part:2, ch:20, seq:101, year:null, month:6, tag:"peace", place:"蒂尔西特", chars:["nikolai","alexander"], gist:"和约序言签订，尼古拉闯进行宫想面递呈文被挡，转而托骑兵将军转递；皇帝出上马旁当众说「我不能，因为法律比我强」。", flag:null },
  { id:"2-2-21", book:2, part:2, ch:21, seq:102, year:null, month:null, tag:"peace", place:"蒂尔西特", chars:["nikolai","napoleon","alexander","boris"], gist:"两国皇帝检阅两军，拿破仑亲手给拉扎列夫挂上勋章，两营同宴言欢；尼古拉想到医院伤员与获罪的杰尼索夫，在饭店拍桌为皇帝辩护。", flag:null },
  { id:"2-3-01", book:2, part:3, ch:1, seq:103, year:1809, month:null, tag:"peace", place:"梁赞", chars:["andrei"], gist:"1809年春，蛰居两年的安德烈在保古察罗伏办农政有成；赴梁赞视察庄园途中遇一棵拒绝春天的老栎树，自谓人生已尽。", flag:null },
  { id:"2-3-02", book:2, part:3, ch:2, seq:104, year:1809, month:5, tag:"peace", place:"奥特拉德诺耶", chars:["andrei","ilya","natasha","sophia"], gist:"安德烈到奥特拉德诺耶找县首席贵族罗斯托夫伯爵办事，被强留过夜；月夜窗前听见娜塔莎无眠的歌唱与赞叹。", flag:null },
  { id:"2-3-03", book:2, part:3, ch:3, seq:105, year:1809, month:6, tag:"peace", place:"保古察罗伏", chars:["andrei","marya"], gist:"归途再见老栎树已换新绿，安德烈顿感重生，决计秋天去彼得堡；独处时对镜沉思，对妹妹玛丽雅变得冷硬。", flag:null },
  { id:"2-3-04", book:2, part:3, ch:4, seq:106, year:1809, month:8, tag:"peace", place:"彼得堡", chars:["andrei","speransky","arakcheev","alexander"], gist:"1809年8月安德烈到彼得堡，正值斯佩兰斯基改革鼎盛；他呈上军事条令意见书，被阿拉克切耶夫冷斥为无须另立新章。", flag:null },
  { id:"2-3-05", book:2, part:3, ch:5, seq:107, year:1809, month:null, tag:"peace", place:"彼得堡", chars:["andrei","speransky","arakcheev"], gist:"柯楚别依家的客厅里，安德烈初见斯佩兰斯基，就贵族特权与荣誉之争各执一词；斯佩兰斯基邀他周三过谈并引荐条令委员会主席。", flag:null },
  { id:"2-3-06", book:2, part:3, ch:6, seq:108, year:1809, month:null, tag:"peace", place:"彼得堡", chars:["andrei","speransky","napoleon"], gist:"安德烈周三与斯佩兰斯基推心置腹长谈，如当年拜服拿破仑般倾慕其理性；一周后进条令委员会任编纂处长，起草人权条文。", flag:null },
  { id:"2-3-07", book:2, part:3, ch:7, seq:109, year:1809, month:null, tag:"peace", place:"彼得堡", chars:["pierre","bazdeev","villarsky"], gist:"皮埃尔成了彼得堡共济会核心，自国外回来后在二级大会上演说主张入世行动，被疑为光明会，与会友激烈争论后拂袖而去。", flag:null },
  { id:"2-3-08", book:2, part:3, ch:8, seq:110, year:1809, month:11, tag:"peace", place:"莫斯科", chars:["pierre","bazdeev","helen","kuragina"], gist:"演说受挫后皮埃尔忧郁症发作，仍赴莫斯科求教巴兹杰耶夫；归来接纳海伦复婚，自谓背起十字架，搬进大宅楼上。", flag:null },
  { id:"2-3-09", book:2, part:3, ch:9, seq:111, year:1809, month:null, tag:"peace", place:"彼得堡", chars:["pierre","helen","boris","napoleon"], gist:"海伦携皮埃尔回彼得堡，以「聪明美丽的迷娘」名头主持沙龙；得势的保里斯成了常客，皮埃尔厌恶却又自缚，不敢猜疑。", flag:null },
  { id:"2-3-10", book:2, part:3, ch:10, seq:112, year:1809, month:null, tag:"peace", place:"彼得堡", chars:["pierre","boris","bazdeev"], gist:"皮埃尔日记：他主持把保里斯接纳入会并充任导师，憎恨与自责交缠；接连的怪梦与巴兹杰耶夫来信提醒他尽夫妻义务。", flag:null },
  { id:"2-3-11", book:2, part:3, ch:11, seq:113, year:1809, month:null, tag:"peace", place:"彼得堡", chars:["ilya","vera","berg","countess_r"], gist:"罗斯托夫家破产般迁居彼得堡，别尔格向薇拉求婚成功，订婚月余又逼问陪嫁，老伯爵应下八万期票外加两万现款。", flag:null },
  { id:"2-3-12", book:2, part:3, ch:12, seq:114, year:1809, month:null, tag:"peace", place:"彼得堡", chars:["natasha","boris","countess_r","sophia"], gist:"十六岁的娜塔莎在彼得堡再遇童年情人保里斯；他盘算娶富女却日日登门，两人谁也没提四年前的旧约。", flag:null },
  { id:"2-3-13", book:2, part:3, ch:13, seq:115, year:null, month:null, tag:"peace", place:"彼得堡", chars:["natasha","countess_r","boris","ilya"], gist:"除夕前夜娜塔莎钻进母亲被窝谈保里斯，说自己绝对不出嫁也要他来；伯爵夫人次日找保里斯摊牌，他从此不再登门。", flag:null },
  { id:"2-3-14", book:2, part:3, ch:14, seq:116, year:1809, month:12, tag:"peace", place:"彼得堡", chars:["natasha", "sophia", "countess_r"], gist:"1809年12月31日除夕迎新大舞会之夜，第一次赴宴的娜塔莎整天张罗母女三人梳妆，缝裙别帽，迟到才动身去公馆。", flag:null },
  { id:"2-3-15", book:2, part:3, ch:15, seq:117, year:null, month:null, tag:"peace", place:"彼得堡", chars:["natasha","sophia","countess_r","pierre","helen","anatole","andrei"], gist:"罗斯托夫家踏入灯火通明的舞厅，彼隆斯卡雅指点全场名流：海伦、阿纳托里、皮埃尔，还有穿白军服重获新生的安德烈。", flag:null },
  { id:"2-3-16", book:2, part:3, ch:16, seq:118, year:null, month:null, tag:"peace", place:"彼得堡", chars:["natasha","andrei","pierre","helen","sophia"], gist:"波兰舞轮空，娜塔莎几乎落泪；皮埃尔拉安德烈请她跳华尔兹，两人第二对入场，安德烈被这初次亮相的少女迷住。", flag:null },
  { id:"2-3-17", book:2, part:3, ch:17, seq:119, year:null, month:null, tag:"peace", place:"彼得堡", chars:["natasha","andrei","boris","ilya","pierre"], gist:"科季里昂舞中安德烈向娜塔莎提起奥特拉德诺月夜，脱口想过「她将成为我的妻子」；娜塔莎幸福到顶点，独皮埃尔的闷郁令她不解。", flag:null },
  { id:"2-3-18", book:2, part:3, ch:18, seq:120, year:null, month:null, tag:"peace", place:"彼得堡", chars:["andrei","speransky","berg"], gist:"次日安德烈对国务会议已觉索然；在斯佩兰斯基家晚宴上，做作的笑声与清谈使他幻灭，回望四个月奔走只剩惭愧。", flag:null },
  { id:"2-3-19", book:2, part:3, ch:19, seq:121, year:null, month:null, tag:"peace", place:"彼得堡", chars:["andrei","natasha","ilya"], gist:"安德烈再访罗斯托夫家，听娜塔莎唱歌时没来由落泪；当夜失眠却畅快，盘算退役出国、认真安排儿子的教育。", flag:null },
  { id:"2-3-20", book:2, part:3, ch:20, seq:122, year:null, month:null, tag:"peace", place:"彼得堡", chars:["berg","vera","pierre","boris"], gist:"别尔格乔迁后办小型晚会，拉皮埃尔撑场面；夫妇俩争先待客，处处模仿名门规格，只求一切同别人家一样。", flag:null },
  { id:"2-3-21", book:2, part:3, ch:21, seq:123, year:null, month:null, tag:"peace", place:"彼得堡", chars:["natasha","andrei","pierre","vera","boris"], gist:"别尔格晚会上娜塔莎恹恹无光，安德烈一进门她便重焕神采；薇拉笨拙地试探婚事，安德烈窘迫地坐到娜塔莎身边低声问询。", flag:null },
  { id:"2-3-22", book:2, part:3, ch:22, seq:124, year:null, month:null, tag:"peace", place:"彼得堡", chars:["andrei","natasha","pierre","countess_r","sophia"], gist:"安德烈在罗斯托夫家纠缠整日；深夜向皮埃尔坦白恋爱与娶娜塔莎的决心，皮埃尔强抑忧郁连声劝婚，越为他高兴越觉得自己暗淡。", flag:null },
  { id:"2-3-23", book:2, part:3, ch:23, seq:125, year:null, month:null, tag:"peace", place:"彼得堡", chars:["andrei","old_prince","natasha","countess_r","sophia"], gist:"老公爵有条件地放行：婚期推迟一年。三周后安德烈回彼得堡正式求婚，娜塔莎又惊又喜，唯独害怕那漫长的一年。", flag:null },
  { id:"2-3-24", book:2, part:3, ch:24, seq:126, year:null, month:null, tag:"peace", place:"彼得堡", chars:["andrei","natasha","pierre","ilya","countess_r","sophia"], gist:"秘密订婚期间安德烈天天出入罗斯托夫家；临行前他把娜塔莎托给皮埃尔，告别后娜塔莎麻木数日，两周后才恢复旧观。", flag:null },
  { id:"2-3-25", book:2, part:3, ch:25, seq:127, year:null, month:null, tag:"peace", place:"童山", chars:["old_prince","marya","andrei","bourienne","julie"], gist:"安德烈出国一年间，老公爵在童山愈发乖戾，专拿信仰与孩子折磨玛丽雅；她写信安慰丧兄的裘丽，把一切归于上帝旨意。", flag:null },
  { id:"2-3-26", book:2, part:3, ch:26, seq:128, year:null, month:null, tag:"peace", place:"童山", chars:["marya","andrei","old_prince"], gist:"仲夏安德烈自瑞士写信公布订婚，托玛丽雅试探父亲能否提前婚期；老公爵冷嘲拒绝，玛丽雅萌生出家云游之念又自斥有罪。", flag:null },
  { id:"2-4-01", book:2, part:4, ch:1, seq:129, year:1810, month:null, tag:"peace", place:"奥特拉德诺耶", chars:["nikolai", "natasha", "countess_r", "sophia", "petya"], gist:"家信催尼古拉回来主持家业，他与同僚痛饮告别赶回奥特拉德诺耶；娜塔莎细说与安德烈订婚始末，他心里存疑。", flag:null },
  { id:"2-4-02", book:2, part:4, ch:2, seq:130, year:1810, month:null, tag:"peace", place:"奥特拉德诺耶", chars:["nikolai","ilya","countess_r"], gist:"尼古拉查账怒斥并拳打管家米金卡，随即承认不懂产业；撕碎德鲁别茨基家期票后不过问家事，专事打猎。", flag:null },
  { id:"2-4-03", book:2, part:4, ch:3, seq:131, year:1810, month:9, tag:"peace", place:"奥特拉德诺耶", chars:["nikolai","natasha","petya"], gist:"解冻天正宜围狼，丹尼洛探知狼窝迁往禁伐林；尼古拉想独自出动，娜塔莎与彼嘉执意跟去。", flag:null },
  { id:"2-4-04", book:2, part:4, ch:4, seq:132, year:1810, month:9, tag:"peace", place:"奥特拉德诺耶", chars:["nikolai","ilya","natasha","petya"], gist:"百余条狗围禁伐林，大叔与尼古拉布阵，老伯爵在守候点夸夸其谈；老狼从他眼皮底下突围，丹尼洛怒追。", flag:null },
  { id:"2-4-05", book:2, part:4, ch:5, seq:133, year:1810, month:9, tag:"peace", place:"奥特拉德诺耶", chars:["nikolai","ilya"], gist:"老狼朝尼古拉奔来，卡拉伊咬住狼喉又被挣脱；丹尼洛下马活擒捆扎，猎队把活狼驮回集合场。", flag:null },
  { id:"2-4-06", book:2, part:4, ch:6, seq:134, year:1810, month:9, tag:"peace", place:"奥特拉德诺耶", chars:["nikolai","natasha","petya"], gist:"伊拉金的猎人抢走罗斯托夫家狗嘴里的狐狸，两队几乎动手；尼古拉反与对头结交合猎，鲁加伊夺兔压过名狗。", flag:null },
  { id:"2-4-07", book:2, part:4, ch:7, seq:135, year:1810, month:9, tag:"peace", place:"奥特拉德诺耶", chars:["natasha","nikolai","petya"], gist:"夜宿大叔家，家奴围观下马的小姐，阿尼西雅摆出盛宴；大叔弹吉他，娜塔莎跳俄罗斯舞，归途自感无上幸福。", flag:null },
  { id:"2-4-08", book:2, part:4, ch:8, seq:136, year:1810, month:null, tag:"peace", place:"奥特拉德诺耶", chars:["countess_r","nikolai","sophia","natasha","ilya"], gist:"伯爵家入不敷出，伯爵夫人想让尼古拉娶富家女裘丽挽救家业，尼古拉只爱宋尼雅；安德烈来信再推迟婚期。", flag:null },
  { id:"2-4-09", book:2, part:4, ch:9, seq:137, year:1810, month:12, tag:"peace", place:"奥特拉德诺耶", chars:["natasha","nikolai","sophia","ilya","countess_r","petya"], gist:"圣诞假期第三天，娜塔莎思念未婚夫坐立不宁，各处差遣仆人、躲到柜后弹旧曲；茶桌上她扑着母亲要人回来。", flag:null },
  { id:"2-4-10", book:2, part:4, ch:10, seq:138, year:1810, month:12, tag:"peace", place:"奥特拉德诺耶", chars:["natasha","nikolai","sophia","petya","ilya","countess_r"], gist:"兄妹琴声中忆童年幻事，娜塔莎破例唱得动人心魄；家奴化装队闯入，年轻人扮装乘雪橇月光出游。", flag:null },
  { id:"2-4-11", book:2, part:4, ch:11, seq:139, year:1810, month:12, tag:"peace", place:null, chars:["nikolai","sophia","natasha"], gist:"梅留科夫家化装宴饮，老姑娘讲捉鸡占卜怪谈；宋尼雅独闯谷仓听声，尼古拉追去，月光柴堆后两人定情。", flag:null },
  { id:"2-4-12", book:2, part:4, ch:12, seq:140, year:1810, month:12, tag:"peace", place:"奥特拉德诺耶", chars:["nikolai","natasha","sophia"], gist:"归途雪橇上尼古拉向娜塔莎表明与宋尼雅永不分离；夜里双镜占卜，宋尼雅失口说看见了喜盈盈的未婚夫。", flag:null },
  { id:"2-4-13", book:2, part:4, ch:13, seq:141, year:null, month:null, tag:"peace", place:"奥特拉德诺耶", chars:["nikolai","countess_r","ilya","natasha","sophia"], gist:"尼古拉宣布决娶宋尼雅，伯爵夫人拒祝福并迁怒甥女，娜塔莎周旋斡旋免遭决裂；月底伯爵携娜塔莎宋尼雅赴莫斯科。", flag:null },
  { id:"2-5-01", book:2, part:5, ch:1, seq:142, year:null, month:null, tag:"peace", place:"莫斯科", chars:["pierre"], gist:"婚约与恩师之死接连传来，皮埃尔的修身热情熄灭，退回到莫斯科的宴饮与俱乐部，用忙碌逃避人生疑问。", flag:null },
  { id:"2-5-02", book:2, part:5, ch:2, seq:143, year:null, month:null, tag:"peace", place:"莫斯科", chars:["old_prince","marya","bourienne"], gist:"老公爵带玛丽雅进莫斯科，成了反政府派核心；私下他家对女儿专横发作，为袒护布莉恩摔手杖、把仆人送兵。", flag:null },
  { id:"2-5-03", book:2, part:5, ch:3, seq:144, year:1811, month:null, tag:"peace", place:"莫斯科", chars:["old_prince","marya","pierre","boris","rastopchin","mativier","bourienne"], gist:"命名日清晨老公爵斥法国医生是间谍并将其赶出，扬言同女儿分开；午宴宾客议论奥登堡事件与对法政策。", flag:null },
  { id:"2-5-04", book:2, part:5, ch:4, seq:145, year:null, month:null, tag:"peace", place:"莫斯科", chars:["pierre","marya","boris"], gist:"宴散后皮埃尔点破保里斯猎取富家女的算盘；玛丽雅哭诉受父亲逼迫，托他留意那位还不认识的未来嫂嫂。", flag:null },
  { id:"2-5-05", book:2, part:5, ch:5, seq:146, year:null, month:null, tag:"peace", place:"莫斯科", chars:["boris","julie","anna_mikh","anatole","vasily"], gist:"保里斯在忧郁成风的裘丽家周旋一月举棋不定；闻华西里公爵派阿纳托里来娶她，赌气求婚，当场得手。", flag:null },
  { id:"2-5-06", book:2, part:5, ch:6, seq:147, year:1812, month:1, tag:"peace", place:"莫斯科", chars:["ilya","natasha","sophia","ahrosimova"], gist:"一月底伯爵带娜塔莎、宋尼雅借住阿赫罗西莫娃家，她包办嫁妆与行程，先教娜塔莎如何讨婆家欢喜。", flag:null },
  { id:"2-5-07", book:2, part:5, ch:7, seq:148, year:null, month:null, tag:"peace", place:"莫斯科", chars:["natasha","ilya","marya","old_prince","bourienne","sophia","ahrosimova"], gist:"娜塔莎随父拜访保尔康斯基家遭怠慢：老公爵穿睡袍出面奚落，姑嫂绝口不提婚事；玛丽雅事后写信修好。", flag:null },
  { id:"2-5-08", book:2, part:5, ch:8, seq:149, year:null, month:null, tag:"peace", place:"莫斯科", chars:["natasha","sophia","ilya","helen","anatole","dolokhov","boris","julie","ahrosimova"], gist:"当晚全家去看歌剧：娜塔莎与宋尼雅的包厢引人瞩目，海伦、波斯装束的陶洛霍夫与迟到的阿纳托里先后入画。", flag:null },
  { id:"2-5-09", book:2, part:5, ch:9, seq:150, year:null, month:null, tag:"peace", place:"莫斯科", chars:["natasha","helen","anatole","ilya","boris","pierre","sophia"], gist:"台上戏文拙劣，台下却喝彩不断；阿纳托里隔着乐池痴望娜塔莎，海伦主动攀谈，把她叫到身边同看后几幕。", flag:null },
  { id:"2-5-10", book:2, part:5, ch:10, seq:151, year:null, month:null, tag:"peace", place:"莫斯科", chars:["anatole","natasha","helen","ilya","sophia"], gist:"阿纳托里进海伦包厢直言相撩，讨走鲜花作保证，散场时又握住她手腕。娜塔莎归家自责，惊觉对未婚夫的感情已遭破坏。", flag:null },
  { id:"2-5-11", book:2, part:5, ch:11, seq:152, year:null, month:null, tag:"peace", place:"莫斯科", chars:["anatole", "dolokhov", "pierre", "natasha"], gist:"补叙阿纳托里：在波兰被强娶后抛妻瞒婚，挥金自谓无罪；陶洛霍夫看准他的痴心，有意把他驱上歪路。", flag:null },
  { id:"2-5-12", book:2, part:5, ch:12, seq:153, year:null, month:null, tag:"peace", place:"莫斯科", chars:["ahrosimova","helen","natasha","ilya","marya","old_prince"], gist:"阿赫罗西莫娃代探婚事碰壁，劝罗斯托夫家先回乡；海伦趁势登门，邀兄妹赴自家朗诵晚会，替哥哥搭线。", flag:null },
  { id:"2-5-13", book:2, part:5, ch:13, seq:154, year:null, month:null, tag:"peace", place:"莫斯科", chars:["natasha","anatole","helen","ilya","mativier"], gist:"晚会上阿纳托里寸步不离：跳舞搂腰、小厅拦路强吻。娜塔莎彻夜在两个同样真切的爱人之间挣扎。", flag:null },
  { id:"2-5-14", book:2, part:5, ch:14, seq:155, year:null, month:null, tag:"peace", place:"莫斯科", chars:["natasha","marya","anatole","ilya","ahrosimova","dolokhov"], gist:"玛丽雅来信求和；娜塔莎却收到陶洛霍夫代笔的阿纳托里情书，读罢认定自己爱的已不是未婚夫。", flag:null },
  { id:"2-5-15", book:2, part:5, ch:15, seq:156, year:null, month:null, tag:"peace", place:"莫斯科", chars:["sophia","natasha","anatole","marya","andrei","ahrosimova"], gist:"宋尼雅夜读情书，追问阿纳托里为何瞒着来历；娜塔莎回信玛丽雅声明已回绝安德烈，并与好友翻脸。", flag:null },
  { id:"2-5-16", book:2, part:5, ch:16, seq:157, year:null, month:null, tag:"peace", place:"莫斯科", chars:["anatole","dolokhov","balaga","natasha"], gist:"诱拐部署就绪：马车、护照、两万卢布与两名顶罪的证婚人；陶洛霍夫算账警告，阿纳托里灌醉车夫巴拉加。", flag:null },
  { id:"2-5-17", book:2, part:5, ch:17, seq:158, year:null, month:null, tag:"peace", place:"莫斯科", chars:["anatole","dolokhov","balaga","ahrosimova"], gist:"阿纳托里摔杯话别，三驾雪橇横冲而至后门；他随引路的人进院，等着的却是夫人的跟班，陶洛霍夫把他拖出。", flag:null },
  { id:"2-5-18", book:2, part:5, ch:18, seq:159, year:null, month:null, tag:"peace", place:"莫斯科", chars:["ahrosimova", "natasha", "sophia", "ilya"], gist:"阿赫罗西莫娃截下条子，痛骂娜塔莎、锁人候贼；计破后竭力瞒住伯爵。娜塔莎枯坐两日，仍痴心等他消息。", flag:null },
  { id:"2-5-19", book:2, part:5, ch:19, seq:160, year:null, month:null, tag:"peace", place:"莫斯科", chars:["pierre","ahrosimova","natasha","ilya","sophia","anatole","andrei"], gist:"皮埃尔从特维尔归来被请来作证：阿纳托里早有妻室；伯爵诉女儿擅自退婚，娜塔莎逼他当面发誓。", flag:null },
  { id:"2-5-20", book:2, part:5, ch:20, seq:161, year:null, month:null, tag:"peace", place:"莫斯科", chars:["pierre","anatole","helen","natasha"], gist:"皮埃尔遍寻不着，在妻子客厅揪住阿纳托里拖进书房，索回情书、勒令离开莫斯科；对方只讨道歉，次日去了彼得堡。", flag:null },
  { id:"2-5-21", book:2, part:5, ch:21, seq:162, year:null, month:null, tag:"peace", place:"莫斯科", chars:["andrei", "pierre", "marya", "old_prince", "natasha", "sophia", "speransky"], gist:"娜塔莎偷服砒霜刚脱险；安德烈回到莫斯科，从父亲手里拿到退婚信，交皮埃尔送还信物，自认无力宽恕。", flag:null },
  { id:"2-5-22", book:2, part:5, ch:22, seq:163, year:1812, month:null, tag:"peace", place:"阿尔巴特街", chars:["pierre","natasha","sophia","ahrosimova","andrei"], gist:"皮埃尔送还信物、允为娜塔莎转求安德烈饶恕，情急吐露愿以自由之身求婚；归途阿尔巴特上空悬着一八一二年彗星。", flag:null },
  { id:"3-1-01", book:3, part:1, ch:1, seq:164, year:1812, month:6, tag:"essay", place:"莫斯科", chars:["napoleon","alexander"], gist:"史论：一八一二年六月法军越境，战争爆发。作者驳外交失误、个人野心等单一起因，论帝王只是历史事件的标签。", flag:null },
  { id:"3-1-02", book:3, part:1, ch:2, seq:165, year:1812, month:6, tag:"war", place:"莫斯科", chars:["napoleon"], gist:"拿破仑离开德累斯顿驰抵前线，在涅曼河边指挥大军渡河；波兰枪骑兵当众跳河泅渡表忠心，淹死数十人。", flag:null },
  { id:"3-1-03", book:3, part:1, ch:3, seq:166, year:1812, month:6, tag:"war", place:"维尔诺", chars:["alexander","boris","helen","arakcheev"], gist:"亚历山大驻维尔诺毫无作战计划，在别尼生别墅舞会上闻法军渡河，誓言不媾和，次日致书拿破仑；保里斯抢先探知机密。", flag:null },
  { id:"3-1-04", book:3, part:1, ch:4, seq:167, year:1812, month:6, tag:"war", place:null, chars:["alexander","murat"], gist:"巴拉歇夫凌晨带着亚历山大的信到涅曼河畔法军哨所，遭盘查，又被自封那不勒斯王的缪拉拦住闲谈开战责任。", flag:null },
  { id:"3-1-05", book:3, part:1, ch:5, seq:168, year:1812, month:6, tag:"war", place:"维尔诺", chars:["davout"], gist:"达武在棚屋冷遇并软禁巴拉歇夫，收下信件不許他与人交谈；四天后他被带进法军占领的维尔诺，等待拿破仑接见。", flag:null },
  { id:"3-1-06", book:3, part:1, ch:6, seq:169, year:1812, month:6, tag:"war", place:"维尔诺", chars:["napoleon"], gist:"拿破仑在维尔诺接见巴拉歇夫，口称不愿开战，却拒绝撤至涅曼河西岸的要求，夸耀兵力，辱骂亚历山大的顾问。", flag:null },
  { id:"3-1-07", book:3, part:1, ch:7, seq:170, year:1812, month:6, tag:"war", place:"维尔诺", chars:["napoleon"], gist:"次日拿破仑设宴又待咖啡，向巴拉歇夫打听莫斯科的教堂与道路，拉使臣耳朵示恩，交回信送客；和谈之门就此关闭。", flag:null },
  { id:"3-1-08", book:3, part:1, ch:8, seq:171, year:1812, month:null, tag:"peace", place:"童山", chars:["andrei","kutuzov","old_prince","marya","bourienne","nikolushka"], gist:"安德烈寻阿纳托里不获，先随库图佐夫在土耳其任职，开战后请求调入西路军。路过童山因布莉恩与父亲吵翻，怏怏离家。", flag:null },
  { id:"3-1-09", book:3, part:1, ch:9, seq:172, year:1812, month:6, tag:"war", place:"德里萨", chars:["andrei","barclay"], gist:"安德烈到德里萨报到，闲住期间看穿行辕中理论派、进攻派、巴克莱派、别尼生派等九个派系；希施科夫上书请皇帝离军安民。", flag:null },
  { id:"3-1-10", book:3, part:1, ch:10, seq:173, year:1812, month:6, tag:"war", place:"德里萨", chars:["andrei"], gist:"皇帝传召安德烈，米肖盛赞德里萨工事；别尼生邸中开非正式会议，安德烈打量迷信理论的普法尔，看出此人垮台在即。", flag:null },
  { id:"3-1-11", book:3, part:1, ch:11, seq:174, year:1812, month:6, tag:"war", place:"德里萨", chars:["andrei", "bennigsen", "volzogen"], gist:"法军包抄的假情报引出行辕紧急会议，各方献策争吵，唯普法尔坚信计划无懈可击。安德烈断言没有军事科学，请旨下到部队。", flag:null },
  { id:"3-1-12", book:3, part:1, ch:12, seq:175, year:1812, month:7, tag:"war", place:"维尔诺", chars:["nikolai","iljin","lavrushka"], gist:"尼古拉得知娜塔莎退婚仍不返乡，致信宋尼雅约战后团聚；部队向边境节节后退，暴雨夜扎营，同僚夸谈拉耶夫斯基战功，他暗疑其虚。", flag:null },
  { id:"3-1-13", book:3, part:1, ch:13, seq:176, year:1812, month:7, tag:"peace", place:null, chars:["nikolai","iljin","lavrushka"], gist:"会战前夜，骠骑兵挤进小酒店避雨，围着军医年轻的妻子敬茶打牌，做国王者吻手为罚；医生愁闷，军官们乐得深夜不睡。", flag:null },
  { id:"3-1-14", book:3, part:1, ch:14, seq:177, year:1812, month:7, tag:"war", place:"奥斯特罗夫诺", chars:["nikolai","iljin"], gist:"破晓时部队开赴奥斯特罗夫诺，尼古拉骑着顿河骏马毫不胆怯，伊林强作镇定；枪骑兵下山冲击法国龙骑兵，本队奉命上山掩护炮兵。", flag:null },
  { id:"3-1-15", book:3, part:1, ch:15, seq:178, year:1812, month:7, tag:"war", place:"奥斯特罗夫诺", chars:["nikolai"], gist:"尼古拉不等命令率连冲垮龙骑兵，砍伤俘获一名有酒窝的法国军官。他得圣乔治勋章并升任营长，却为那一刀苦闷不解。", flag:null },
  { id:"3-1-16", book:3, part:1, ch:16, seq:179, year:1812, month:null, tag:"peace", place:"莫斯科", chars:["natasha","countess_r","ilya","sophia"], gist:"罗斯托夫全家回莫斯科守护病重的娜塔莎。作者借医生议论：治病是满足病人对同情与行动的渴望；娜塔莎靠青春之力渐愈。", flag:null },
  { id:"3-1-17", book:3, part:1, ch:17, seq:180, year:1812, month:null, tag:"peace", place:"莫斯科", chars:["natasha","pierre","countess_r"], gist:"娜塔莎回避一切欢乐，只有皮埃尔与彼嘉能使她安定；她随邻居别洛娃斋戒礼拜，从晨祷到领圣餐，在忏悔中觉得可以重新开始。", flag:null },
  { id:"3-1-18", book:3, part:1, ch:18, seq:181, year:1812, month:7, tag:"peace", place:"莫斯科", chars:["natasha","countess_r","pierre"], gist:"战报与流言交炽，皇帝离军回都。罗斯托夫家做礼拜，堂上新诵抗击入侵者的祷文，娜塔莎为亲人与仇敌祷告，把自己交给上帝。", flag:null },
  { id:"3-1-19", book:3, part:1, ch:19, seq:182, year:1812, month:7, tag:"peace", place:"莫斯科", chars:["pierre","rastopchin"], gist:"皮埃尔痴迷推算启示录，认定拿破仑是六百六十六的兽，自己名字合数命中有大作为；他从拉斯托普庆处取得尼古拉授勋的命令。", flag:null },
  { id:"3-1-20", book:3, part:1, ch:20, seq:183, year:1812, month:7, tag:"peace", place:"莫斯科", chars:["pierre","natasha","ilya","countess_r","sophia","petya"], gist:"罗斯托夫家星期日午餐：娜塔莎重新唱歌，问皮埃尔安德烈会否原谅她；老伯爵听读告民众书落泪，彼嘉闹参军被斥，皮埃尔决意回避。", flag:null },
  { id:"3-1-21", book:3, part:1, ch:21, seq:184, year:1812, month:7, tag:"peace", place:"莫斯科", chars:["petya","alexander","ilya"], gist:"彼嘉瞒着家人挤进克里姆林宫觐见皇帝，被人潮挤昏又获救上炮台；皇帝在阳台撒饼干，他抢到一枚，回家便以逃跑要挟参军。", flag:null },
  { id:"3-1-22", book:3, part:1, ch:22, seq:185, year:1812, month:7, tag:"peace", place:"莫斯科", chars:["pierre","ilya"], gist:"克里姆林宫里贵族与商人同赴非常会议：退伍海军力陈民团之弊，皮埃尔主张先明军情再谈贡献，反被激昂的爱国贵族围攻。", flag:null },
  { id:"3-1-23", book:3, part:1, ch:23, seq:186, year:1812, month:7, tag:"peace", place:"莫斯科", chars:["rastopchin","alexander","pierre","ilya"], gist:"拉斯托普庆催促定议，贵族当场认千丁十；皇帝进厅致谢，对商人讲话时落泪。皮埃尔愿出一千名壮丁，老伯爵答应送彼嘉从军。", flag:null },
  { id:"3-2-01", book:3, part:2, ch:1, seq:187, year:1812, month:8, tag:"essay", place:"斯摩棱斯克", chars:["napoleon","alexander","barclay","bagration","bennigsen"], gist:"史论：一八一二年的灾难没有作者——拿破仑凭冲动深入，俄军因内讧退却，斯摩棱斯克失守，焚城激起同仇敌忾。", flag:null },
  { id:"3-2-02", book:3, part:2, ch:2, seq:188, year:1812, month:8, tag:"peace", place:"童山", chars:["old_prince","marya","bourienne","mikhail"], gist:"老公爵与玛丽雅口角后称病一周，病愈断绝布莉恩往来，忙于造屋立嗣；得安德烈告警来信，仍拒认战事已至维切布斯克。", flag:null },
  { id:"3-2-03", book:3, part:2, ch:3, seq:189, year:null, month:null, tag:"peace", place:"童山", chars:["old_prince","alpatych","mikhail","tihon"], gist:"老公爵留阿尔巴端奇两个时辰交办斯摩棱斯克采购；夜里重读安德烈来信才懂敌情紧迫，追想波将金时代。", flag:null },
  { id:"3-2-04", book:3, part:2, ch:4, seq:190, year:1812, month:8, tag:"war", place:"斯摩棱斯克", chars:["alpatych","andrei","berg"], gist:"阿尔巴端奇进城办事，省长避而不答；午后法军炮轰斯摩棱斯克，全城火起。安德烈在火场指示火速送全家去莫斯科。", flag:null },
  { id:"3-2-05", book:3, part:2, ch:5, seq:191, year:null, month:8, tag:"war", place:"童山", chars:["andrei","alpatych","bagration"], gist:"安德烈行军途中绕回童山，庄园残破、家人已走；巴格拉基昂致阿拉克切耶夫的信痛斥巴克莱弃守斯摩棱斯克之罪。", flag:null },
  { id:"3-2-06", book:3, part:2, ch:6, seq:192, year:1812, month:8, tag:"peace", place:"彼得堡", chars:["anna_sherer","vasily","helen","bilbin"], gist:"彼得堡两大客厅各持亲法反法论调。华西里公爵先讥库图佐夫是瞎子，八月八日获知他当上总司令，立刻改口赞美。", flag:null },
  { id:"3-2-07", book:3, part:2, ch:7, seq:193, year:null, month:null, tag:"war", place:"莫斯科", chars:["napoleon","lavrushka","nikolai"], gist:"拿破仑自维亚兹马向莫斯科进发，途中提审掳来的哥萨克仆役拉夫鲁施卡，放他回营；拉夫鲁施卡傍晚寻回主人尼古拉。", flag:null },
  { id:"3-2-08", book:3, part:2, ch:8, seq:194, year:null, month:null, tag:"peace", place:"保古察罗伏", chars:["old_prince","marya","tihon","bourienne"], gist:"老公爵拒弃童山，检阅民团途中中风；转往保古察罗伏缠绵三周，清晨忽然清醒向女儿致谢求恕，当天再度中风去世。", flag:null },
  { id:"3-2-09", book:3, part:2, ch:9, seq:195, year:1812, month:8, tag:"peace", place:"保古察罗伏", chars:["alpatych"], gist:"保古察罗伏的草原农民谣诼沸腾，村民会议决定留村等待法军；阿尔巴端奇向村长德龙逼要车辆，农民把马赶进树林。", flag:null },
  { id:"3-2-10", book:3, part:2, ch:10, seq:196, year:null, month:null, tag:"peace", place:"保古察罗伏", chars:["marya","bourienne","mikhail","tihon"], gist:"出殡后玛丽雅闭门不出；布莉恩献上法军安民告示并提议求庇护，玛丽雅受辱愤而决意出走，闻农民缺马断粮，下令放粮。", flag:null },
  { id:"3-2-11", book:3, part:2, ch:11, seq:197, year:null, month:null, tag:"peace", place:"保古察罗伏", chars:["marya"], gist:"玛丽雅到谷仓前见村民，愿赠粮并接济到莫斯科安置；农民疑为诱去当奴隶，齐声回绝，谈判破裂。", flag:null },
  { id:"3-2-12", book:3, part:2, ch:12, seq:198, year:null, month:null, tag:"transition", place:"保古察罗伏", chars:["marya"], gist:"满月之夜玛丽雅重温父亲临终一幕，惊惧难当，逃下楼时正撞见慌张来报的仆妇。", flag:null },
  { id:"3-2-13", book:3, part:2, ch:13, seq:199, year:null, month:8, tag:"peace", place:"保古察罗伏", chars:["nikolai","iljin","lavrushka","alpatych","marya"], gist:"尼古拉到保古察罗伏打探草料，不知庄主是妹妹未婚夫的家；阿尔巴端奇拦马求救，被围的玛丽雅见到救星。", flag:null },
  { id:"3-2-14", book:3, part:2, ch:14, seq:200, year:null, month:null, tag:"peace", place:"保古察罗伏", chars:["nikolai","marya","alpatych","lavrushka"], gist:"尼古拉揍头目、捆绑村长，乱民立散，车队平安上路；握手话别之后，玛丽雅在去莫斯科路上自知初恋，尼古拉也动了心思。", flag:null },
  { id:"3-2-15", book:3, part:2, ch:15, seq:201, year:null, month:null, tag:"war", place:"察廖夫扎伊米歇", chars:["andrei","denisov","kutuzov","barclay"], gist:"察廖夫扎伊米歇阅兵日，安德烈结识杰尼索夫，听他大讲切断法军交通线的游击计划；库图佐夫听完报告，只就抢劫事发令。", flag:null },
  { id:"3-2-16", book:3, part:2, ch:16, seq:202, year:null, month:null, tag:"war", place:"察廖夫扎伊米歇", chars:["kutuzov","andrei"], gist:"库图佐夫想留安德烈在身旁却不勉强，追忆奥斯特里茨军旗，推崇耐心和时间最好的武器；安德烈回到团里感到安心。", flag:null },
  { id:"3-2-17", book:3, part:2, ch:17, seq:203, year:null, month:null, tag:"peace", place:"莫斯科", chars:["pierre","julie"], gist:"莫斯科大祸将至却享乐如常。裘丽晚会上众人调侃皮埃尔办民团，又议他做娜塔莎的骑士，还谈起玛丽雅获救抵城。", flag:null },
  { id:"3-2-18", book:3, part:2, ch:18, seq:204, year:null, month:null, tag:"transition", place:"莫斯科", chars:["pierre"], gist:"皮埃尔在广场看到受鞭刑的法国嫌疑犯，决意上前线；二十四日离开莫斯科，路过舍瓦尔季诺战地，赶到莫扎依斯克。", flag:null },
  { id:"3-2-19", book:3, part:2, ch:19, seq:205, year:1812, month:8, tag:"essay", place:"鲍罗金诺", chars:["napoleon","kutuzov","barclay","bagration"], gist:"史论：鲍罗金诺会战双方都是无奈之举。史书伪称择定设防阵地会战，实为舍瓦尔季诺失守后仓促以半数兵力迎战。", flag:null },
  { id:"3-2-20", book:3, part:2, ch:20, seq:206, year:null, month:8, tag:"war", place:"莫斯科", chars:["pierre"], gist:"皮埃尔赴战地途中遇伤兵车队，钟声与军歌交织；军医叹担架人手不足，劝他找总司令，民团农民正抢挖工事。", flag:null },
  { id:"3-2-21", book:3, part:2, ch:21, seq:207, year:null, month:null, tag:"war", place:"鲍罗金诺", chars:["pierre","kutuzov","bennigsen"], gist:"皮埃尔登岗辨不出阵地，军官指点中央两翼的部署；斯摩棱斯克圣像抬上山，库图佐夫上前叩拜。", flag:null },
  { id:"3-2-22", book:3, part:2, ch:22, seq:208, year:null, month:null, tag:"war", place:"鲍罗金诺", chars:["pierre","boris","dolokhov","kutuzov","bennigsen"], gist:"会战前夜营地：保里斯周旋于库图佐夫与别尼生两派之间；陶洛霍夫请派险任务又与皮埃尔拥抱释怨；别尼生带皮埃尔巡视防线。", flag:null },
  { id:"3-2-23", book:3, part:2, ch:23, seq:209, year:null, month:null, tag:"war", place:"鲍罗金诺", chars:["pierre","bennigsen"], gist:"别尼生带皮埃尔遍历未完工工事，远处遥望可能是拿破仑的骑马人；左翼他不经报告，擅自把杜契科夫的埋伏部队调上高地。", flag:null },
  { id:"3-2-24", book:3, part:2, ch:24, seq:210, year:null, month:null, tag:"war", place:"鲍罗金诺", chars:["andrei","pierre"], gist:"会战前夜，安德烈卧破仓房，以死的白光照破爱情、荣誉与祖国的幻象；皮埃尔来营探问，遭他冷语相迎。", flag:null },
  { id:"3-2-25", book:3, part:2, ch:25, seq:211, year:null, month:null, tag:"war", place:"鲍罗金诺", chars:["andrei","pierre","volzogen"], gist:"战前夜话：安德烈宣称胜负全靠士气，痛斥德国参谋理论，主张作战不留俘虏，与皮埃尔诀别；夜不能眠，重忆娜塔莎。", flag:null },
  { id:"3-2-26", book:3, part:2, ch:26, seq:212, year:null, month:8, tag:"war", place:"鲍罗金诺", chars:["napoleon"], gist:"二十五日夜晚瓦卢耶法营：拿破仑接见巴黎来使，摆出父子深情让老近卫军瞻仰罗马王画像，又口授莫斯科战役的命令。", flag:null },
  { id:"3-2-27", book:3, part:2, ch:27, seq:213, year:1812, month:8, tag:"essay", place:"鲍罗金诺", chars:["napoleon","davout"], gist:"史论：拿破仑的会战部署细看不过四项命令，竟无一项能够执行；他离战场太远，所谓天才指挥只是史家曲笔。", flag:null },
  { id:"3-2-28", book:3, part:2, ch:28, seq:214, year:null, month:8, tag:"essay", place:"鲍罗金诺", chars:["napoleon"], gist:"史论：驳拿破仑伤风致败说——皇帝没有打死一个人，几十万士兵自己要打，他不过是貌似统帅的历史工具。", flag:null },
  { id:"3-2-29", book:3, part:2, ch:29, seq:215, year:null, month:null, tag:"war", place:"鲍罗金诺", chars:["napoleon"], gist:"拿破仑战前夜扮作从容的外科医生，与拉普对谈到深夜，巡看岗哨；五点半驰往舍瓦尔季诺，炮声四起，会战开始。", flag:null },
  { id:"3-2-30", book:3, part:2, ch:30, seq:216, year:null, month:null, tag:"war", place:"鲍罗金诺", chars:["pierre","kutuzov"], gist:"会战之晨皮埃尔被炮声惊醒，与库图佐夫同登高岗，看尽雾、烟与刺刀交织的壮丽全景，按捺不住，随将军纵马奔向渡口。", flag:null },
  { id:"3-2-31", book:3, part:2, ch:31, seq:217, year:null, month:null, tag:"war", place:"鲍罗金诺", chars:["pierre"], gist:"皮埃尔误闯拉耶夫斯基炮垒受火之洗礼：看炮手在弹雨里说笑、心中燃起怒火；弹尽官倒，他帮着去搬弹药被炸倒在地。", flag:null },
  { id:"3-2-32", book:3, part:2, ch:32, seq:218, year:null, month:null, tag:"war", place:"鲍罗金诺", chars:["pierre"], gist:"皮埃尔逃回炮垒，本能掐住扑来的法国军官；炮垒夺回，昨日相熟的炮手已死伤净尽；硝烟外厮杀仍烈到极点。", flag:null },
  { id:"3-2-33", book:3, part:2, ch:33, seq:219, year:null, month:null, tag:"essay", place:"鲍罗金诺", chars:["napoleon","murat","davout"], gist:"史论：会战进程全出个人掌控之外——副官的奏报无不过时，命令无一被执行，阵上几十万人各凭死的冲动行动。", flag:null },
  { id:"3-2-34", book:3, part:2, ch:34, seq:220, year:null, month:null, tag:"war", place:"鲍罗金诺", chars:["napoleon"], gist:"法军将领接连求援，拿破仑自觉如赌徒入彀，尝到噩梦般的恐惧；巡视谢苗诺夫伤亡后不肯远耗近卫军，拨马而回。", flag:null },
  { id:"3-2-35", book:3, part:2, ch:35, seq:221, year:null, month:null, tag:"war", place:"鲍罗金诺", chars:["kutuzov","volzogen","barclay"], gist:"库图佐夫只养士气不定部署：怒斥报败的伏尔佐根，坚称明日进攻；这道命令借军中神秘联系传遍各部，抚慰动摇的军心。", flag:null },
  { id:"3-2-36", book:3, part:2, ch:36, seq:222, year:null, month:null, tag:"war", place:"鲍罗金诺", chars:["andrei"], gist:"后备团在几百门炮轰击下枯坐八小时，心绪尽付琐事；榴弹在安德烈脚边旋转，他喊着想活，被霰弹击穿腹部抬往救护站。", flag:null },
  { id:"3-2-37", book:3, part:2, ch:37, seq:223, year:null, month:null, tag:"war", place:"鲍罗金诺", chars:["andrei","anatole"], gist:"救护帐篷里锯割号叫不断；安德烈术后认出邻桌刚截去大腿的是阿纳托里，想起娜塔莎，流下悲悯与博爱之泪。", flag:null },
  { id:"3-2-38", book:3, part:2, ch:38, seq:224, year:null, month:null, tag:"essay", place:"鲍罗金诺", chars:["napoleon"], gist:"战场惨象摧垮拿破仑心神，他不再想要胜利，却仍机械地下令添炮；作者引他圣赫勒拿自辩，斥其刽子手角色下的自欺。", flag:null },
  { id:"3-2-39", book:3, part:2, ch:39, seq:225, year:null, month:null, tag:"essay", place:"鲍罗金诺", chars:["napoleon"], gist:"会战收场：万尸卧田，落雨如劝停，双方都疑心为何相杀。史论：俄军以士气胜，鲍罗金诺是法军覆灭的致命伤。", flag:null },
  { id:"3-3-01", book:3, part:3, ch:1, seq:226, year:null, month:null, tag:"essay", place:null, chars:["napoleon"], gist:"史论序言：运动不可切成断片来理解；历史规律当从群众无数意志的「微分」中求，抛开帝王与统帅个人。", flag:null },
  { id:"3-3-02", book:3, part:3, ch:2, seq:227, year:null, month:null, tag:"essay", place:"莫斯科", chars:["kutuzov"], gist:"史论：鲍罗金诺后俄军连日非退不可；统帅身处矛盾事件之流，放弃莫斯科并非在战前书房里一次决定。", flag:null },
  { id:"3-3-03", book:3, part:3, ch:3, seq:228, year:null, month:null, tag:"war", place:"波克朗山", chars:["kutuzov","bennigsen","rastopchin"], gist:"将军们聚在波克朗山库图佐夫的凳子四周，众口一词说阵地守不住；别尼生坚持应战，别有用心，老人看破，召齐将领移往菲里。", flag:null },
  { id:"3-3-04", book:3, part:3, ch:4, seq:229, year:null, month:null, tag:"war", place:"菲里", chars:["kutuzov","bennigsen","barclay"], gist:"菲里军事会议：别尼生提「守古都还是弃都」，库图佐夫斥问题无意义，借弗里德兰之例驳回夜袭方案，下令撤退。", flag:null },
  { id:"3-3-05", book:3, part:3, ch:5, seq:230, year:1812, month:7, tag:"essay", place:"莫斯科", chars:["rastopchin"], gist:"史论：放弃并焚毁莫斯科不可避免，居民凭内心预感自发撤离；拉斯托普庆的公告与做戏不过是闹剧一场。", flag:null },
  { id:"3-3-06", book:3, part:3, ch:6, seq:231, year:null, month:null, tag:"peace", place:"彼得堡", chars:["helen"], gist:"海伦回到彼得堡，周旋于外国亲王与政府要员之间；耶稣会士趁虚而入引她改宗天主教，她则要教会替她办妥离婚再嫁。", flag:null },
  { id:"3-3-07", book:3, part:3, ch:7, seq:232, year:null, month:8, tag:"peace", place:"彼得堡", chars:["helen","ahrosimova","vasily","bilbin"], gist:"上流社会默认海伦再嫁，唯阿赫罗西莫娃当众痛骂；华西里听之任之。八月初海伦致信皮埃尔索要离婚手续，信送达鲍罗金诺。", flag:null },
  { id:"3-3-08", book:3, part:3, ch:8, seq:233, year:null, month:null, tag:"war", place:"鲍罗金诺", chars:["pierre"], gist:"鲍罗金诺当夜，皮埃尔独自在莫扎依斯克大道上走；三个士兵分他面糊、摸黑送他进城，天明被车夫认出，蜷在马车里过夜。", flag:null },
  { id:"3-3-09", book:3, part:3, ch:9, seq:234, year:null, month:null, tag:"transition", place:"莫斯科", chars:["pierre"], gist:"皮埃尔在莫扎依斯克半梦半悟：士兵纯朴不怕死，这些道理须如套车般串起来。醒后闻法军逼近，退往莫斯科，途中误闻安德烈阵亡。", flag:null },
  { id:"3-3-10", book:3, part:3, ch:10, seq:235, year:null, month:8, tag:"war", place:"莫斯科", chars:["pierre"], gist:"八月三十日皮埃尔回莫斯科，被传去见拉斯托普庆。他在接待室读卫戍司令的荒唐告示，听说商人魏列夏金父子因传单获罪。", flag:null },
  { id:"3-3-11", book:3, part:3, ch:11, seq:236, year:null, month:null, tag:"war", place:"莫斯科", chars:["pierre","rastopchin"], gist:"拉斯托普庆威吓皮埃尔断绝会友来往、即刻离城。皮埃尔夜读妻子索离信函，翌晨悄悄出走；家人自此再不知他的下落。", flag:null },
  { id:"3-3-12", book:3, part:3, ch:12, seq:237, year:null, month:8, tag:"peace", place:"莫斯科", chars:["ilya","countess_r","natasha","petya","sophia"], gist:"罗斯托夫家滞留不走：伯爵夫人忧念两个从军的儿子，彼嘉八月二十八日到家，阖府忙收拾，娜塔莎与彼嘉却无缘由地欢笑。", flag:null },
  { id:"3-3-13", book:3, part:3, ch:13, seq:238, year:null, month:8, tag:"peace", place:"莫斯科", chars:["natasha", "countess_r", "petya", "sophia"], gist:"八月三十一日举宅纷乱。娜塔莎见街上伤员车队，把负伤军官接进自家；伯爵夫人当夜催逼起身，彼嘉带回三山门要打仗的消息。", flag:null },
  { id:"3-3-14", book:3, part:3, ch:14, seq:239, year:null, month:null, tag:"peace", place:"莫斯科", chars:["natasha","andrei"], gist:"深夜装车，娜塔莎把细软紧凑塞进两口大箱，赢得全家信服。半夜一辆带篷马车又抬进一位垂危伤员——安德烈公爵。", flag:null },
  { id:"3-3-15", book:3, part:3, ch:15, seq:240, year:null, month:9, tag:"peace", place:"莫斯科", chars:["ilya","countess_r","natasha","berg"], gist:"九月一日莫斯科人心皇皇，物价骤变。伯爵背着妻子下令卸掉三十辆大车上的行李让给伤员；伯爵夫人哭闹，别尔格来探亲。", flag:null },
  { id:"3-3-16", book:3, part:3, ch:16, seq:241, year:null, month:9, tag:"peace", place:"莫斯科", chars:["natasha","ilya","countess_r","berg","sophia","petya"], gist:"别尔格高谈鲍罗金诺「英勇气概」，还讨要岳家的小柜。娜塔莎怒斥丢弃伤员太可耻，全家让出全部大车，仆从欢腾地搬箱装人。", flag:null },
  { id:"3-3-17", book:3, part:3, ch:17, seq:242, year:null, month:9, tag:"peace", place:"莫斯科", chars:["natasha", "countess_r", "sophia", "pierre", "petya"], gist:"车队启行。宋尼雅识出同行的是垂危的安德烈，瞒着娜塔莎。过苏哈列夫塔楼巧遇穿车夫长袍的皮埃尔，他决意只身留在莫斯科。", flag:null },
  { id:"3-3-18", book:3, part:3, ch:18, seq:243, year:null, month:null, tag:"transition", place:"莫斯科", chars:["pierre"], gist:"皮埃尔借整理遗书躲进亡师巴兹杰耶夫的空宅，嘱老仆盖拉西姆备农民外衣与手枪；他在恩师书房夜不能寐，暗下孤注一掷的决心。", flag:null },
  { id:"3-3-19", book:3, part:3, ch:19, seq:244, year:null, month:9, tag:"war", place:"波克朗山", chars:["napoleon","kutuzov"], gist:"九月一日子夜俄军穿城退走；次日晨拿破仑在波克朗山等候大贵族的代表团，等来的却是全城皆空的禀报，遂下令各门进军。", flag:null },
  { id:"3-3-20", book:3, part:3, ch:20, seq:245, year:null, month:null, tag:"essay", place:"莫斯科", chars:["napoleon"], gist:"史论：空了的莫斯科如失王的蜂巢，形存实亡。拿破仑听到确报后恼怒异常，拒绝入城，夜宿陶罗戈米洛夫门外的旅店。", flag:null },
  { id:"3-3-21", book:3, part:3, ch:21, seq:246, year:null, month:null, tag:"war", place:"莫斯科", chars:["iljin"], gist:"俄军过城时拥堵桥上，士兵涌向中央商场抢掠，商人拦住军官哀告无门；叶尔莫洛夫架炮佯轰，逼开堵路人群才把军队放出。", flag:null },
  { id:"3-3-22", book:3, part:3, ch:22, seq:247, year:null, month:null, tag:"transition", place:"莫斯科", chars:["ilya"], gist:"罗斯托夫家只留三个下人看守空宅。一位落难青年军官来寻伯爵求助，老仆玛芙拉自作主张，把私蓄的二十五卢布塞给了他。", flag:null },
  { id:"3-3-23", book:3, part:3, ch:23, seq:248, year:null, month:null, tag:"war", place:"莫斯科", chars:["rastopchin"], gist:"无主之城：工人与铁匠在酒店前扭打，人群传读拉斯托普庆讨伐「暴徒」的公告；警察局长谎称伯爵还在城中，众人追上他的马车。", flag:null },
  { id:"3-3-24", book:3, part:3, ch:24, seq:249, year:1812, month:9, tag:"essay", place:"莫斯科", chars:["rastopchin","kutuzov"], gist:"库图佐夫半夜一纸冷令，击碎拉斯托普庆「引导民意」的幻梦。他恼怒通宵下令放疯人与囚犯，忽忆魏列夏金：提来见我。", flag:null },
  { id:"3-3-25", book:3, part:3, ch:25, seq:250, year:null, month:9, tag:"war", place:"莫斯科", chars:["rastopchin","kutuzov"], gist:"拉斯托普庆把魏列夏金交给民众，龙骑兵先动刀，青年死于乱拳；他逃往郊外被疯子拦车咒骂，见到库图佐夫只敢埋怨其弃城。", flag:null },
  { id:"3-3-26", book:3, part:3, ch:26, seq:251, year:null, month:null, tag:"essay", place:"莫斯科", chars:["murat"], gist:"缪拉率军入空城，炮轰克里姆林宫门；士兵如水入沙散进宅院，军队自行瓦解。史论：莫斯科非一人所焚，无主的木城非烧不可。", flag:null },
  { id:"3-3-27", book:3, part:3, ch:27, seq:252, year:null, month:9, tag:"war", place:"莫斯科", chars:["pierre"], gist:"九月二日法军逼近皮埃尔的寓所。他半近疯狂，执意要只身刺死拿破仑；半疯的玛卡尔夺手枪放走火，叩门声起——法国人到了。", flag:null },
  { id:"3-3-28", book:3, part:3, ch:28, seq:253, year:null, month:null, tag:"war", place:"莫斯科", chars:["pierre","linguist"], gist:"疯子一枪射偏，皮埃尔扑救仑巴尔大尉，暴露自己懂法语；他替疯子求情获赦，被热心的法国人引为恩人与「同胞」。", flag:null },
  { id:"3-3-29", book:3, part:3, ch:29, seq:254, year:null, month:9, tag:"war", place:"莫斯科", chars:["pierre","linguist"], gist:"皮埃尔与仑巴尔对饮，听他颂拿破仑、谈风月，冲动下倾吐对娜塔莎的旧情，刺杀计划在敌人的温情里泄了气。当夜城里冒起头一把火。", flag:null },
  { id:"3-3-30", book:3, part:3, ch:30, seq:255, year:null, month:9, tag:"transition", place:"梅基希", chars:[], gist:"车队夜宿梅基希。仆人们望见东方天际的火光，老仆丹尼洛听出那是莫斯科，哽咽道出「洁白的母亲」，众人祷告哭泣。", flag:null },
  { id:"3-3-31", book:3, part:3, ch:31, seq:256, year:null, month:null, tag:"peace", place:"梅基希", chars:["natasha","andrei","countess_r","sophia"], gist:"宋尼雅透露安德烈同行重伤，娜塔莎整天魂不守舍。半夜她赤脚摸进厢房，就着烛光看清床上的安德烈公爵，跪到他跟前。", flag:null },
  { id:"3-3-32", book:3, part:3, ch:32, seq:257, year:null, month:null, tag:"peace", place:"梅基希", chars:["andrei","natasha"], gist:"昏迷七日的安德烈醒来索要《福音书》，悟出爱仇敌的神圣之爱；娜塔莎跪在床前求饶恕，他说比以前更爱她。此后她寸步不离护理。", flag:null },
  { id:"3-3-33", book:3, part:3, ch:33, seq:258, year:1809, month:9, tag:"war", place:"莫斯科", chars:["pierre"], gist:"九月三日皮埃尔藏起匕首出门，城中已是火海。路上遇官吏之妇哭丢幼女，他二话不说随使女冲进燃烧的厢房去找孩子。", flag:null },
  { id:"3-3-34", book:3, part:3, ch:34, seq:259, year:null, month:null, tag:"war", place:"莫斯科", chars:["pierre"], gist:"女孩救出火场，皮埃尔又扑向凌辱亚美尼亚女子的法兵，挥拳救人，被枪骑兵拿下；搜出凶器，他当作纵火犯单独关押。", flag:null },
  { id:"4-1-01", book:4, part:1, ch:1, seq:260, year:1812, month:8, tag:"peace", place:"彼得堡", chars:["anna_sherer","vasily","helen","bilbin","hippolyte"], gist:"鲍罗金诺当天，舍勒家照开晚会。华西里公爵朗诵主教献圣像的信，宾客议论海伦夫人突患心绞痛。", flag:null },
  { id:"4-1-02", book:4, part:1, ch:2, seq:261, year:1812, month:8, tag:"peace", place:"彼得堡", chars:["vasily", "helen", "rastopchin", "kutuzov"], gist:"鲍罗金诺捷报传到彼得堡，悲痛集中在库塔伊索夫阵亡上；海伦暴卒，莫斯科失守的消息随后传开，皇帝下诏责问库图佐夫。", flag:null },
  { id:"4-1-03", book:4, part:1, ch:3, seq:262, year:null, month:null, tag:"peace", place:"彼得堡", chars:[], gist:"米肖向亚历山大一世报告莫斯科陷落与大火。皇帝落泪后立誓奋战，宁可同农民啃土豆也不签约，宣称与拿破仑不共戴天。", flag:null },
  { id:"4-1-04", book:4, part:1, ch:4, seq:263, year:1812, month:null, tag:"peace", place:"沃罗涅日", chars:["nikolai"], gist:"尼古拉奉命到沃罗涅日买马，一路上只顾个人安逸；在地主家买下十七匹种马，省长晚会上大出风头，缠上一位文官太太。", flag:null },
  { id:"4-1-05", book:4, part:1, ch:5, seq:264, year:null, month:null, tag:"peace", place:"沃罗涅日", chars:["nikolai"], gist:"省长夫人为尼古拉与玛丽雅公爵小姐做媒，姨妈邀他上门。尼古拉坦陈已允婚宋尼雅、家道艰难，半被说服。", flag:null },
  { id:"4-1-06", book:4, part:1, ch:6, seq:265, year:null, month:null, tag:"peace", place:"沃罗涅日", chars:["nikolai","marya","bourienne"], gist:"尼古拉到姨妈家拜访玛丽雅，爱情让她容光焕发，两人互生好感；省长夫人继续撮合，安排他们在主教面前再见。", flag:null },
  { id:"4-1-07", book:4, part:1, ch:7, seq:266, year:null, month:null, tag:"peace", place:"沃罗涅日", chars:["nikolai","marya","sophia"], gist:"莫斯科失守噩耗传到沃罗涅日，尼古拉与玛丽雅教堂相遇互慰；宋尼雅来信解除婚约，得知安德烈负伤，他送玛丽雅到雅罗斯拉夫尔。", flag:null },
  { id:"4-1-08", book:4, part:1, ch:8, seq:267, year:null, month:null, tag:"peace", place:"莫斯科", chars:["sophia","countess_r","natasha","andrei"], gist:"伯爵夫人含泪求宋尼雅放弃尼古拉；圣三一修道院里，宋尼雅发现圣诞占卦与安德烈卧床情景相符，感伤中写信托给他自由。", flag:null },
  { id:"4-1-09", book:4, part:1, ch:9, seq:268, year:null, month:9, tag:"war", place:"莫斯科", chars:["pierre"], gist:"皮埃尔在莫斯科以纵火嫌疑被拘，与底层犯人同押，遭敷衍定罪式审问；大火蔓延，他们被转到克里木浅滩车棚，等元帅发落。", flag:null },
  { id:"4-1-10", book:4, part:1, ch:10, seq:269, year:null, month:9, tag:"war", place:"莫斯科", chars:["pierre","davout"], gist:"皮埃尔等俘虏被押过废墟，到谢尔巴托夫公馆见达武。他与元帅对视生出人的情感，仍被当间谍带走，悟到杀他的是秩序。", flag:null },
  { id:"4-1-11", book:4, part:1, ch:11, seq:270, year:null, month:null, tag:"war", place:"莫斯科", chars:["pierre"], gist:"皮埃尔被押去陪斩：五名俄国俘虏先后绑在柱前枪毙，最后一个年轻工人死得可怕；俄国人与法国人一样惊恐，他追问这是谁干的。", flag:null },
  { id:"4-1-12", book:4, part:1, ch:12, seq:271, year:null, month:null, tag:"war", place:"莫斯科", chars:["pierre","platon"], gist:"行刑后皮埃尔的信念之弹簧断裂，转入战俘棚；普拉东·卡拉塔耶夫递来烤土豆、讲获罪当兵的旧事，破碎的世界开始修复。", flag:null },
  { id:"4-1-13", book:4, part:1, ch:13, seq:272, year:null, month:null, tag:"war", place:"莫斯科", chars:["pierre","platon"], gist:"皮埃尔在棚中蹲了四个星期；圆脸的卡拉塔耶夫成为朴实真理的化身：耐劳多艺、满口谚语、无我地爱周围所有人，印象从此不变。", flag:null },
  { id:"4-1-14", book:4, part:1, ch:14, seq:273, year:null, month:null, tag:"peace", place:"雅罗斯拉夫尔", chars:["marya","natasha","sophia","countess_r","ilya","nikolushka"], gist:"玛丽雅不顾劝阻带侄儿绕道赶到雅罗斯拉夫尔；罗斯托夫家周旋不肯报信，娜塔莎跑来痛哭，玛丽雅从她脸上明白哥哥已无希望。", flag:null },
  { id:"4-1-15", book:4, part:1, ch:15, seq:274, year:null, month:null, tag:"peace", place:"雅罗斯拉夫尔", chars:["andrei","marya","natasha","nikolushka"], gist:"病室里安德烈用冰冷敌意的目光看人间事，拿妹妹的婚事说给活人听，生者与垂死者已不能相互理解；两女轮流侍疾祈祷。", flag:null },
  { id:"4-1-16", book:4, part:1, ch:16, seq:275, year:null, month:null, tag:"peace", place:"雅罗斯拉夫尔", chars:["andrei","natasha","marya","nikolushka","ilya"], gist:"安德烈夜半向娜塔莎告白，又梦见拼力顶不住死神推门，惊醒后说死就是觉醒；领圣餐、为子祝福，平静离世，两女为他合眼。", flag:null },
  { id:"4-2-01", book:4, part:2, ch:1, seq:276, year:1812, month:null, tag:"essay", place:"塔鲁季诺", chars:["napoleon"], gist:"史论：所谓侧翼进军被算成某个人的天才决策，其实它和一切历史事件一样，由无数偶然条件一步一步凑成，谁也没能预见。", flag:null },
  { id:"4-2-02", book:4, part:2, ch:2, seq:277, year:1812, month:10, tag:"essay", place:"塔鲁季诺", chars:["kutuzov","napoleon"], gist:"史论：军队转向产粮地区只是退却推力的自然延续。", flag:null },
  { id:"4-2-03", book:4, part:2, ch:3, seq:278, year:1812, month:10, tag:"war", place:"塔鲁季诺", chars:["kutuzov", "bennigsen", "murat"], gist:"彼得堡的远程计划与参谋部倾轧夹住统帅，皇帝手谕痛责他迟迟不救莫斯科；一个哥萨克追野兔撞上法军左翼，进攻再也拦不住。", flag:null },
  { id:"4-2-04", book:4, part:2, ch:4, seq:279, year:1812, month:10, tag:"war", place:"塔鲁季诺", chars:["kutuzov"], gist:"作战令签发了，纵队在纸上按时到位歼敌；传令军官揣着副本找叶尔莫洛夫找了一整天，直到夜里在前哨的舞宴上才把命令交出手。", flag:null },
  { id:"4-2-05", book:4, part:2, ch:5, seq:280, year:null, month:null, tag:"war", place:"塔鲁季诺", chars:["kutuzov","bennigsen"], gist:"进攻日清晨，库图佐夫赶到集合地才发现部队根本没动；他把两个无辜的参谋骂到发抖，自觉成了全军笑柄，只好再次同意推迟一天。", flag:null },
  { id:"4-2-06", book:4, part:2, ch:6, seq:281, year:1812, month:null, tag:"war", place:"塔鲁季诺", chars:["murat","bennigsen"], gist:"十月五日夜军队悄然开拔：禁高声、禁吸烟、禁马嘶；多数纵队走了一整夜却走错地方，只有奥尔洛夫伯爵的哥萨克小队准时到位。", flag:null },
  { id:"4-2-07", book:4, part:2, ch:7, seq:282, year:null, month:null, tag:"war", place:"塔鲁季诺", chars:["kutuzov","bennigsen","murat"], gist:"正面纵队按兵不动，只有哥萨克出了力，乱仗后将领们反得钻石勋章。", flag:null },
  { id:"4-2-08", book:4, part:2, ch:8, seq:283, year:1812, month:10, tag:"essay", place:"莫斯科", chars:["napoleon"], gist:"史论：拿下莫斯科后拿破仑握有双倍兵力，保住优势无须天才，他却纵兵劫掠、进退不定。", flag:null },
  { id:"4-2-09", book:4, part:2, ch:9, seq:284, year:null, month:null, tag:"essay", place:"莫斯科", chars:["napoleon"], gist:"占领者分头施政：监视俄军各路、派两个使者去彼得堡求和、处决纵火犯、烧掉拉斯托普庆的公馆、给莫斯科颁市政章程，还开戏院。", flag:null },
  { id:"4-2-10", book:4, part:2, ch:10, seq:285, year:1812, month:10, tag:"essay", place:"莫斯科", chars:["napoleon"], gist:"史论：这些指令像脱离机件的指针空转——使者被拒、布告无人睬、伪钞不值钱、抢劫禁而不止。", flag:null },
  { id:"4-2-11", book:4, part:2, ch:11, seq:286, year:1812, month:10, tag:"peace", place:"莫斯科", chars:["pierre","platon"], gist:"皮埃尔光脚在棚外晒太阳、逗那条没有名字的野狗，法国班长待他客气。", flag:null },
  { id:"4-2-12", book:4, part:2, ch:12, seq:287, year:null, month:null, tag:"peace", place:"莫斯科", chars:["pierre","platon","andrei"], gist:"被俘四个星期，皮埃尔在极端困苦里得到苦寻半生的平静：死刑抹掉了国事、名誉与妻子，饿食渴饮便算幸福。", flag:null },
  { id:"4-2-13", book:4, part:2, ch:13, seq:288, year:1812, month:10, tag:"war", place:"莫斯科", chars:["pierre","platon"], gist:"法军拔营，俘虏被编队驱走；皮埃尔替垂死的病号求情，只换来变了脸的班长和压过呻吟的鼓声。", flag:null },
  { id:"4-2-14", book:4, part:2, ch:14, seq:289, year:null, month:null, tag:"war", place:"莫斯科", chars:["pierre"], gist:"俘虏被卷进出城的辎重洪流，车上堆满抢来的财物和涂脂抹粉的女眷；夜宿时押送队翻了脸，还传出就地枪决掉队者的话。", flag:null },
  { id:"4-2-15", book:4, part:2, ch:15, seq:290, year:1812, month:10, tag:"war", place:"塔鲁季诺", chars:["kutuzov","dolokhov","napoleon","murat"], gist:"又来一名议和军使，库图佐夫照旧回绝。", flag:null },
  { id:"4-2-16", book:4, part:2, ch:16, seq:291, year:1812, month:null, tag:"war", place:"塔鲁季诺", chars:["barclay","bennigsen","kutuzov","napoleon"], gist:"雨夜信使换马奔到列塔舍夫卡总司令部；值班将军一听拿破仑到了福明斯科耶便即刻穿靴起身，只预感到参谋部那班人将乱出主意。", flag:null },
  { id:"4-2-17", book:4, part:2, ch:17, seq:292, year:1812, month:10, tag:"war", place:"塔鲁季诺", chars:["kutuzov"], gist:"库图佐夫夜不能寐，独眼看罩着黑暗：他等一个月，等的正是鲍罗金诺那一击致命的证据。", flag:null },
  { id:"4-2-18", book:4, part:2, ch:18, seq:293, year:null, month:null, tag:"essay", place:"小雅罗斯拉韦茨", chars:["kutuzov","napoleon"], gist:"史论：此后库图佐夫的全部作为是拦住军队去作无益的追击。", flag:null },
  { id:"4-2-19", book:4, part:2, ch:19, seq:294, year:1812, month:10, tag:"essay", place:"维亚兹马", chars:["kutuzov"], gist:"史论：溃军把斯摩棱斯克当作眼前的乐土，成千上万的人像原子般聚成一国撤退。", flag:null },
  { id:"4-3-01", book:4, part:3, ch:1, seq:295, year:1812, month:null, tag:"essay", place:"莫斯科", chars:["napoleon","kutuzov","alexander"], gist:"史论：鲍罗金诺后法军占领莫斯科却不战而亡——俄国丢开击剑规则，抡起人民战争的大棒。", flag:null },
  { id:"4-3-02", book:4, part:3, ch:2, seq:296, year:1812, month:null, tag:"essay", place:null, chars:[], gist:"史论：游击战以分散攻集中，违反兵法却常胜；兵力等于质量乘士气，士气是兵学回避的未知数。", flag:null },
  { id:"4-3-03", book:4, part:3, ch:3, seq:297, year:null, month:10, tag:"war", place:"斯摩棱斯克", chars:["denisov"], gist:"游击队蜂起截杀溃兵。杰尼索夫盯上开往斯摩棱斯克的法军运输队，瞒着上级拟与陶洛霍夫约期合击。", flag:null },
  { id:"4-3-04", book:4, part:3, ch:4, seq:298, year:null, month:null, tag:"war", place:"维亚兹马", chars:["denisov","petya"], gist:"秋雨林间，杰尼索夫苦等陶洛霍夫的回音；彼嘉替将军送信来到队里，喜见旧识，请求留下参战。", flag:null },
  { id:"4-3-05", book:4, part:3, ch:5, seq:299, year:null, month:null, tag:"war", place:null, chars:["denisov","petya"], gist:"杰尼索夫带彼嘉到林边俯瞰法军营盘，部署步兵哥萨克分路夹攻；探子季洪白昼潜入敌阵遭枪击追逐。", flag:null },
  { id:"4-3-06", book:4, part:3, ch:6, seq:300, year:null, month:null, tag:"war", place:null, chars:["denisov","petya"], gist:"季洪吹嘘夜袭抓舌头的经历，原来他嫌第一个俘虏不中用已下杀手。军官来报陶洛霍夫夜间即到，杰尼索夫转怒为喜。", flag:null },
  { id:"4-3-07", book:4, part:3, ch:7, seq:301, year:null, month:10, tag:"war", place:"维亚兹马", chars:["petya","denisov"], gist:"彼嘉留在游击队，与军官挤桌同食，殷勤分送葡萄干和火石，又惦记挨冻的法国小鼓手，把他叫到跟前安抚。", flag:null },
  { id:"4-3-08", book:4, part:3, ch:8, seq:302, year:null, month:null, tag:"war", place:"莫斯科", chars:["dolokhov","denisov","petya"], gist:"陶洛霍夫到队，主张不留俘虏，与看重军人荣誉的杰尼索夫激烈争执；他不顾劝阻，带彼嘉扮法军去摸敌营。", flag:null },
  { id:"4-3-09", book:4, part:3, ch:9, seq:303, year:null, month:null, tag:"war", place:null, chars:["dolokhov","petya"], gist:"两人身披法军衣帽夜闯敌营，骗过桥头哨兵，在篝火旁盘问部队虚实后从容脱身；彼嘉兴奋得拉住陶洛霍夫亲吻。", flag:null },
  { id:"4-3-10", book:4, part:3, ch:10, seq:304, year:null, month:null, tag:"war", place:null, chars:["petya","denisov"], gist:"侦察归来彼嘉兴奋难眠，叫哥萨克连夜替他把马刀开刃，倚车打盹时幻听庄严的赋格曲，神游仙境直到天亮。", flag:null },
  { id:"4-3-11", book:4, part:3, ch:11, seq:305, year:null, month:null, tag:"war", place:null, chars:["petya","denisov","dolokhov","pierre"], gist:"黎明总攻，彼嘉喝令冲锋冲入庄园，头部中弹阵亡；杰尼索夫闻声恸哭，此战救出的俘虏中有皮埃尔。", flag:null },
  { id:"4-3-12", book:4, part:3, ch:12, seq:306, year:null, month:10, tag:"war", place:"莫斯科", chars:["pierre","platon"], gist:"皮埃尔随俘虏队苦行西撤，一路减员冻毙；他悟出苦难有界限、人能自持，却刻意回避日渐垂危的普拉东。", flag:null },
  { id:"4-3-13", book:4, part:3, ch:13, seq:307, year:null, month:10, tag:"war", place:"莫斯科", chars:["pierre","platon"], gist:"雨中行军，皮埃尔回想普拉东夜讲的苦役犯故事：无辜老人代人受过，真凶自首，寻到时他已被上帝饶恕死去。", flag:null },
  { id:"4-3-14", book:4, part:3, ch:14, seq:308, year:null, month:null, tag:"war", place:"斯摩棱斯克", chars:["pierre","platon"], gist:"元帅巡视车队，病弱的普拉东守在桦树旁招呼皮埃尔；皮埃尔装作不见瘸腿走开，身后一声枪响，普拉东被处决。", flag:null },
  { id:"4-3-15", book:4, part:3, ch:15, seq:309, year:null, month:null, tag:"war", place:"鲍罗金诺", chars:["pierre","dolokhov","denisov"], gist:"皮埃尔梦中以变动的球悟生命与普拉东之死；枪声惊醒，游击队救下俘虏，陶洛霍夫冷面点收降兵，杰尼索夫葬彼嘉。", flag:null },
  { id:"4-3-16", book:4, part:3, ch:16, seq:310, year:null, month:null, tag:"essay", place:"斯摩棱斯克", chars:["napoleon"], gist:"史论：上冻后法军溃退愈惨，七万余人西逃仅存三万余；命令文报皆成具文，人人只顾保命逃命。", flag:null },
  { id:"4-3-17", book:4, part:3, ch:17, seq:311, year:null, month:null, tag:"essay", place:"斯摩棱斯克", chars:["napoleon"], gist:"史论：追逃如蒙眼捉迷藏，法军沿不利旧路狂奔，各军连夜绕圈脱身；奈伊万人断后，到奥尔沙只剩一千。", flag:null },
  { id:"4-3-18", book:4, part:3, ch:18, seq:312, year:null, month:null, tag:"essay", place:"卡卢加", chars:["napoleon"], gist:"史论：驳史家把无谓溃逃美化为深谋远虑；以伟大二字抹去善恶标准，恰恰是承认极端渺小。", flag:null },
  { id:"4-3-19", book:4, part:3, ch:19, seq:313, year:1812, month:null, tag:"essay", place:"克拉斯诺耶", chars:["kutuzov","napoleon"], gist:"史论：优势俄军为何未全俘法军？截俘计划本是虚构；人民只求光复国土，军队当如驱牲口的鞭子而非迎头痛击。", flag:null },
  { id:"4-4-01", book:4, part:4, ch:1, seq:314, year:null, month:12, tag:"peace", place:"雅罗斯拉夫尔", chars:["natasha","marya","alpatych"], gist:"安德烈死后娜塔莎与玛丽雅各自守悲。玛丽雅先被家务唤起，娜塔莎拒绝同行独坐凝望生死彼岸，年末忽闻彼嘉阵亡。", flag:null },
  { id:"4-4-02", book:4, part:4, ch:2, seq:315, year:null, month:null, tag:"peace", place:"雅罗斯拉夫尔", chars:["natasha", "countess_r", "sophia", "marya"], gist:"伯爵闻讯恸哭，伯爵夫人精神错乱。娜塔莎忘掉自己的悲伤彻夜守护母亲，三天后夫人清醒，第一次放声大哭。", flag:null },
  { id:"4-4-03", book:4, part:4, ch:3, seq:316, year:null, month:1, tag:"peace", place:"雅罗斯拉夫尔", chars:["natasha", "marya"], gist:"娜塔莎三星期守护治愈了自己的创伤，爱复苏即生命复苏。她与玛丽雅结成相依为命的友谊，一月底同赴莫斯科。", flag:null },
  { id:"4-4-04", book:4, part:4, ch:4, seq:317, year:null, month:null, tag:"essay", place:"克拉斯诺耶", chars:["kutuzov","napoleon"], gist:"维亚兹马之后俄军急行追击与法军溃逃同样损耗过半。克拉斯诺耶三天乱仗俘敌两万六，将军们却把没有捉住拿破仑归罪库图佐夫。", flag:null },
  { id:"4-4-05", book:4, part:4, ch:5, seq:318, year:1812, month:null, tag:"essay", place:"鲍罗金诺", chars:["kutuzov","napoleon"], gist:"史论：为库图佐夫辩诬。从鲍罗金诺到维尔诺主旨如一：驱走法军、减轻军民苦难；洞察人民意志者不容于史家。", flag:null },
  { id:"4-4-06", book:4, part:4, ch:6, seq:319, year:1812, month:11, tag:"war", place:"克拉斯诺耶", chars:["kutuzov"], gist:"克拉斯诺耶首日傍晚，库图佐夫赴多勃罗耶途中察看可怜的法军俘虏，在团前讲话：敌人强大时狠打，如今可怜他们，因为他们也是人。", flag:null },
  { id:"4-4-07", book:4, part:4, ch:7, seq:320, year:1812, month:11, tag:"war", place:"克拉斯诺耶", chars:[], gist:"克拉斯诺耶最后一夜，缩到九百人的步枪团自掘宿营地：士兵喊号子搬篱笆挡风，篝火边烤虱子过夜，长官们在农舍谋划明日切断法军。", flag:null },
  { id:"4-4-08", book:4, part:4, ch:8, seq:321, year:1812, month:11, tag:"war", place:"克拉斯诺耶", chars:["napoleon"], gist:"篝火边的士兵闲谈：冻饿掉队的惨状、莫扎依斯克法军尸骸不腐的传闻、普拉托夫两捉拿破仑的吹牛；听说五连来了两个法国人。", flag:null },
  { id:"4-4-09", book:4, part:4, ch:9, seq:322, year:1812, month:11, tag:"war", place:"克拉斯诺耶", chars:["linguist"], gist:"半夜两个法国人出林投火：病重的仑巴尔被士兵抬去取暖，连声称朋友；勤务兵莫列尔酒后与士兵对唱法国歌，满营欢笑。", flag:null },
  { id:"4-4-10", book:4, part:4, ch:10, seq:323, year:1812, month:12, tag:"war", place:"维尔诺", chars:["kutuzov", "bennigsen"], gist:"史论：别列津纳渡河只是溃败的过渡阶段，彼得堡设伏计划破产，将军群起归咎库图佐夫。", flag:null },
  { id:"4-4-11", book:4, part:4, ch:11, seq:324, year:1812, month:12, tag:"essay", place:"维尔诺", chars:["kutuzov","alexander"], gist:"宴会上皇帝嫌库图佐夫不解欧洲战争的意义，司令部改组夺其兵权。史论：人民战争的角色演完，这位代表只剩一条死路。", flag:null },
  { id:"4-4-12", book:4, part:4, ch:12, seq:325, year:null, month:1, tag:"peace", place:"奥廖尔", chars:["pierre","platon"], gist:"获释后皮埃尔在奥廖尔病倒三个月。消息渐明：安德烈与海伦已死。他尝到完全的自由——人生目的不复存在，因为处处看见上帝。", flag:null },
  { id:"4-4-13", book:4, part:4, ch:13, seq:326, year:null, month:1, tag:"peace", place:"奥廖尔", chars:["pierre","villarsky"], gist:"奥廖尔的皮埃尔变了：善听人言，赢得公爵小姐、医生与意大利军官的心。他心里有了新法官，拒还债又决定去彼得堡偿债修房。", flag:null },
  { id:"4-4-14", book:4, part:4, ch:14, seq:327, year:1813, month:null, tag:"essay", place:"莫斯科", chars:["rastopchin"], gist:"史论：焚后的莫斯科像被毁的蚁穴聚拢群蚁。从哄抢尸体财物到农夫进城贱卖粮食、商人搭棚复业，一万五千居民两周翻倍。", flag:null },
  { id:"4-4-15", book:4, part:4, ch:15, seq:328, year:null, month:1, tag:"peace", place:"莫斯科", chars:["pierre","marya","natasha"], gist:"一月底皮埃尔抵莫斯科，访玛丽雅谈安德烈临终。烛光下他没认出瘦削的黑衣女客就是娜塔莎，一经识破便自惊又爱上了她。", flag:null },
  { id:"4-4-16", book:4, part:4, ch:16, seq:329, year:null, month:null, tag:"peace", place:"莫斯科", chars:["pierre","natasha","marya","andrei"], gist:"娜塔莎头一次向皮埃尔倾吐安德烈临终三周的往事，说完撞门奔出。皮埃尔方觉整个世界只剩她一人，玛丽雅留他共进晚餐。", flag:null },
  { id:"4-4-17", book:4, part:4, ch:17, seq:330, year:null, month:null, tag:"peace", place:"莫斯科", chars:["pierre","natasha","marya"], gist:"深夜长谈：皮埃尔对娜塔莎细讲俘虏见闻与普拉东之死，她说他准是做了善事。三点钟不散，皮埃尔说有生活就有幸福，她哭了。", flag:null },
  { id:"4-4-18", book:4, part:4, ch:18, seq:331, year:null, month:null, tag:"peace", place:"莫斯科", chars:["pierre","natasha","marya"], gist:"皮埃尔整夜踱步决意求婚，推迟行期连日往玛丽雅家坐。他向公爵小姐吐露心事，她许诺帮忙；临别娜塔莎轻声说：我等您。", flag:null },
  { id:"4-4-19", book:4, part:4, ch:19, seq:332, year:null, month:null, tag:"essay", place:"莫斯科", chars:["pierre"], gist:"史论兼心理：等回音的皮埃尔高兴得发疯，觉得人人都在为他的幸福忙碌，无缘无故地爱人。他认定这一时期的看法永远正确。", flag:null },
  { id:"4-4-20", book:4, part:4, ch:20, seq:333, year:null, month:null, tag:"peace", place:"莫斯科", chars:["natasha","marya","pierre"], gist:"娜塔莎自那晚苏醒：换了面容声气，不再提往事。她在门口追问皮埃尔说了什么，羞怯承认爱他；玛丽雅伤感而原谅了她。", flag:null },
  { id:"5-1-01", book:5, part:1, ch:1, seq:334, year:1820, month:null, tag:"essay", place:"彼得堡", chars:["alexander","napoleon","arakcheev"], gist:"史论：一八一二年后再过七年，历史海洋表面平静。历数史学家对亚历山大一世«反动»的谴责，驳其祸福标准因时而异。", flag:null },
  { id:"5-1-02", book:5, part:1, ch:2, seq:335, year:null, month:null, tag:"essay", place:null, chars:["napoleon","alexander"], gist:"史论：机会与天才皆无名之词。以养肥待宰的公羊作比，主张放弃终极目的之问，历史人物的一生方显连贯必然。", flag:null },
  { id:"5-1-03", book:5, part:1, ch:3, seq:336, year:null, month:null, tag:"essay", place:"莫斯科", chars:["napoleon"], gist:"史论：自西向东的进军需要集团、传统崩解与一个能为暴行辩护的首领；逐一拆解拿破仑凭机会登极至兵败莫斯科的各个环节。", flag:null },
  { id:"5-1-04", book:5, part:1, ch:4, seq:337, year:null, month:null, tag:"essay", place:"蒂尔西特", chars:["napoleon","alexander"], gist:"史论：波拿巴孤身返国演完最后一角，卸装的演员指给观众看；亚历山大成事后弃权力，如蜜蜂蜇人、采蜜各说一端。", flag:null },
  { id:"5-1-05", book:5, part:1, ch:5, seq:338, year:1813, month:null, tag:"peace", place:"莫斯科", chars:["ilya","countess_r","nikolai","sophia","natasha","pierre"], gist:"叙事：一八一三年娜塔莎出嫁，同年老伯爵病逝，遗产债大于产。尼古拉接债破产，为避牢狱改做文官，与母亲、宋尼雅同居节度。", flag:null },
  { id:"5-1-06", book:5, part:1, ch:6, seq:339, year:null, month:null, tag:"peace", place:"莫斯科", chars:["marya","nikolai","countess_r","sophia","bourienne"], gist:"玛丽雅到莫斯科探望，遭尼古拉冷遇；他回访敷衍将走，她忍不住追问缘由，两人相认，隔阂顿消。", flag:null },
  { id:"5-1-07", book:5, part:1, ch:7, seq:340, year:1814, month:null, tag:"peace", place:"童山", chars:["nikolai","marya","sophia","countess_r"], gist:"叙事：一八一四年秋两人成婚，迁居童山。尼古拉三年还清债，成了懂农民、讥新法的老派东家，产业日增。", flag:null },
  { id:"5-1-08", book:5, part:1, ch:8, seq:341, year:null, month:null, tag:"peace", place:"童山", chars:["nikolai","marya","natasha","sophia"], gist:"尼古拉当众打了村长，妻子含泪一劝他便认错，摔戒为记，此后动怒先转戒指。写童山家宅清简、命名日宾客满堂的常年规矩。", flag:null },
  { id:"5-1-09", book:5, part:1, ch:9, seq:342, year:1820, month:12, tag:"peace", place:"童山", chars:["nikolai","marya","natasha","pierre","denisov","countess_r","sophia","mikhail"], gist:"叙事：一八二〇年十二月五日圣尼古拉节前夜，童山午餐二十副餐具。玛丽雅疑心丈夫对她生气，孩子闯进睡房，夫妻和解，皮埃尔到。", flag:null },
  { id:"5-1-10", book:5, part:1, ch:10, seq:343, year:1813, month:null, tag:"peace", place:"莫斯科", chars:["natasha","pierre","countess_r","sophia","marya"], gist:"婚后七年：娜塔莎成了多子母亲，不唱歌、不修边幅，把全部力气用在丈夫与家上；全家都按她揣度的皮埃尔心意运转。", flag:null },
  { id:"5-1-11", book:5, part:1, ch:11, seq:344, year:null, month:null, tag:"peace", place:"童山", chars:["natasha","pierre","denisov","nikolai","marya"], gist:"娜塔莎放丈夫去彼得堡，限期四周；超期两周她忧躁成疾，喂坏奶病了儿子。他归来，她又喜又怒，杰尼索夫才认出她本来面目。", flag:null },
  { id:"5-1-12", book:5, part:1, ch:12, seq:345, year:null, month:null, tag:"peace", place:"童山", chars:["pierre","natasha","nikolushka","countess_r","marya"], gist:"童山各圈子都盼皮埃尔归来；小尼古拉视他为英雄偶像。他买齐全家礼物，家计反好转；老伯爵夫人靠牌阵与耳背消磨残生。", flag:null },
  { id:"5-1-13", book:5, part:1, ch:13, seq:346, year:null, month:null, tag:"peace", place:"童山", chars:["pierre","natasha","nikolai","marya","denisov","countess_r","sophia"], gist:"茶炊旁谈彼得堡近况：圣经会当权、阿拉克切耶夫得势，老伯爵夫人为高里岑被贬不悦离席；隔壁孩子为两只袜子欢呼。", flag:null },
  { id:"5-1-14", book:5, part:1, ch:14, seq:347, year:null, month:null, tag:"peace", place:"童山", chars:["pierre","nikolai","denisov","natasha","marya","nikolushka","arakcheev"], gist:"书房争论：皮埃尔说好人该结社自保，尼古拉答以宣誓效忠、若受命讨伐必立刻出动。娜塔莎解围；小尼古拉问亡父会否赞成。", flag:null },
  { id:"5-1-15", book:5, part:1, ch:15, seq:348, year:1812, month:12, tag:"peace", place:"童山", chars:["nikolai","marya","nikolushka","pierre","natasha"], gist:"晚饭后尼古拉读妻子的教育日记，钦佩而自惭；夫妻各说白日之争与孤侄，他畅想赎回奥特拉德诺，她只愧疚自己爱得不公。", flag:null },
  { id:"5-1-16", book:5, part:1, ch:16, seq:349, year:null, month:null, tag:"peace", place:"童山", chars:["natasha","pierre","nikolai","marya","nikolushka","platon","andrei","arakcheev"], gist:"娜塔莎与皮埃尔不讲逻辑地私语，谈嫉妒、普拉东与眼下幸福。夜深小尼古拉噩梦：率蛛丝大军，姑父搬出阿拉克切耶夫。", flag:null },
  { id:"5-2-01", book:5, part:2, ch:1, seq:350, year:null, month:null, tag:"essay", place:"莫斯科", chars:["alexander","helen","napoleon"], gist:"史论：近代史学口头上否定神意，实际上仍把群众领袖当历史动力并预设目标，对一七八九以来的动乱答非所问。", flag:null },
  { id:"5-2-02", book:5, part:2, ch:2, seq:351, year:null, month:null, tag:"essay", place:null, chars:["alexander","napoleon"], gist:"史论：逐一驳斥三类史家——传记家归因英雄权力，通史家拼凑分力又退回权力，文化史家抬出观念，都答不了动力问题。", flag:null },
  { id:"5-2-03", book:5, part:2, ch:3, seq:352, year:null, month:null, tag:"essay", place:null, chars:["alexander","napoleon"], gist:"史论：火车头之喻——鬼推、轮转、吹烟三种解释各对应英雄力、合力、智力活动；权力仍是现有史料的唯一兑换手段。", flag:null },
  { id:"5-2-04", book:5, part:2, ch:4, seq:353, year:null, month:null, tag:"essay", place:null, chars:["alexander","napoleon"], gist:"史论：检视『群众意志交给统治者』的三种交权说，以普加乔夫、十字军为例证明它们只是假设，写出的仍是君王与作家的历史。", flag:null },
  { id:"5-2-05", book:5, part:2, ch:5, seq:354, year:null, month:null, tag:"essay", place:null, chars:["alexander","napoleon"], gist:"史论：牛群与带头牛之喻揭穿『权力即意志总和』的同义反复；经验证明权力确凿存在，须从时间与命令同执行者的关系重新界定。", flag:null },
  { id:"5-2-06", book:5, part:2, ch:6, seq:355, year:null, month:null, tag:"essay", place:"彼得堡", chars:["napoleon"], gist:"史论：命令不自发、不成系列便不生效，拿破仑从未下过『远征俄国』一令；权力如圆锥体，直接行动愈少者发号施令愈多。", flag:null },
  { id:"5-2-07", book:5, part:2, ch:7, seq:356, year:null, month:null, tag:"essay", place:null, chars:[], gist:"史论：先有事件，后有人借辩解之名发号施令，如船前波浪；权力不是事件之因，运动由全体参加者推动，参加愈多责任愈少。", flag:null },
  { id:"5-2-08", book:5, part:2, ch:8, seq:357, year:null, month:null, tag:"essay", place:null, chars:[], gist:"史论：历史每一步都撞上自由意志问题——人作为观察对象服从规律，作为意识主体自感自由；以生理学否定自由的论者只看见一面。", flag:null },
  { id:"5-2-09", book:5, part:2, ch:9, seq:358, year:null, month:null, tag:"essay", place:null, chars:["napoleon"], gist:"史论：历史不必定义自由与必然本身，只研究二者在具体条件下的结合；每一行动自由与必然成反比，随观察视角而增减。", flag:null },
  { id:"5-2-10", book:5, part:2, ch:10, seq:359, year:null, month:null, tag:"essay", place:null, chars:[], gist:"史论：无论视角如何变化，完全的自由与完全的必然都不可设想；理性与意识是两个互相规定的认识来源，自由为内容、必然为形式。", flag:null },
  { id:"5-2-11", book:5, part:2, ch:11, seq:360, year:null, month:null, tag:"essay", place:null, chars:[], gist:"史论：承认有不服从规律的意志便没有历史规律；历史应如数学与牛顿那样放弃寻求原因，转找无限小因素的共同规律。", flag:null },
  { id:"5-2-12", book:5, part:2, ch:12, seq:361, year:null, month:null, tag:"essay", place:"莫斯科", chars:["alexander","kutuzov","liza","marya","murat","napoleon","nikolai"], gist:"史论：统计学、地理学、政治经济学已证人口、迁徙、政体皆有规律，把事件归因自由意志的旧史观动摇，之争犹如哥白尼革命。", flag:null },
];

if (typeof module !== "undefined") module.exports = { CHAPTERS };
